module Studio.IndexHtml

open Giraffe.ViewEngine

let page =
    html [ _lang "en" ] [
        head [] [
            meta [ attr "charset" "utf-8" ]
            meta [ attr "name" "viewport"; attr "content" "width=device-width, initial-scale=1" ]
            meta [ attr "name" "color-scheme"; attr "content" "dark" ]
            meta [ attr "http-equiv" "Content-Security-Policy"; attr "content" "connect-src 'none'; object-src 'none'; base-uri 'none'" ]
            meta [ attr "name" "description"; attr "content" "Local audio and lyric timing studio." ]
            title [] [
                str "studio"
            ]
            style [] [
                    rawText (""":root{--bg:#0d1010;--panel:#131817;--line:#29312d;--text:#e5ede8;--muted:#8d9b93;--accent:#90efb8;--red:#e99991;color-scheme:dark;font:13px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,input,textarea,select{font:inherit}button,a,input,textarea,select{-webkit-tap-highlight-color:transparent}button{padding:9px 13px;border:1px solid #354039;border-radius:5px;background:#1a211d;color:var(--text);cursor:pointer;white-space:nowrap}button:hover:not(:disabled){border-color:#6b8576;background:#222c26}button:disabled{opacity:.35;cursor:not-allowed}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.primary{background:var(--accent);color:#0d2015;border-color:var(--accent)}.primary:hover:not(:disabled){background:#b2f7cf;color:#0d2015}.text-button{border:0;background:transparent;padding:3px 0;color:var(--muted);font-size:11px}.text-button:hover:not(:disabled){background:transparent;color:var(--text)}[hidden]{display:none!important}a{color:inherit}.topbar{padding:21px 3.8%;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line)}.wordmark{display:flex;align-items:center;gap:10px;font:600 24px/1.2 system-ui,sans-serif;letter-spacing:-.8px;text-decoration:none}.mark{color:var(--accent);font:26px monospace}.version{align-self:flex-end;margin:0 0 2px 8px;color:#69776f;font:10px monospace;letter-spacing:0}nav{display:flex;gap:8px}nav button{font-size:11px}nav button span{margin-left:9px}main{max-width:1600px;padding:24px 3.8% 35px;margin:auto}.workspace-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:18px;color:var(--muted);font-size:10px;letter-spacing:1.5px}.workspace-heading i,.status i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent);margin-right:9px}.workbench{display:grid;grid-template-columns:minmax(270px,345px) minmax(0,1fr);gap:24px}.editor{display:flex;flex-direction:column;gap:15px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:19px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:17px}.section-heading h1,.section-heading h2{font:500 12px monospace;margin:0}.section-heading h1 span,.section-heading h2 span,summary>span:first-child{color:#65776b;margin-right:9px;font-size:10px}.section-heading>span{font-size:10px;color:var(--muted)}.dropzone{border:1px dashed #3a4e40;border-radius:5px;min-height:144px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:18px 8px;cursor:pointer;gap:8px;transition:background .15s}.dropzone:hover,.dropzone.dragging{background:#1d2b22;border-color:var(--accent)}.dropzone strong{font-size:11px;font-weight:400;word-break:break-all}.dropzone small{font-size:9px;color:#819187}.upload-icon{font-size:23px;color:var(--accent);line-height:1;margin-bottom:4px}.file-input{display:none}.title-row{display:flex;gap:12px;margin-top:18px}.title-row label:first-child{flex:1;min-width:0}label{display:block;color:var(--muted);font-size:10px}input,textarea,select{width:100%;display:block;margin-top:7px;background:#0e1310;color:var(--text);border:1px solid #303e34;border-radius:4px;padding:9px}input:focus,textarea:focus,select:focus{outline:1px solid var(--accent);border-color:var(--accent)}input[type=color]{height:36px;width:43px;padding:4px;cursor:pointer}.lyrics-editor textarea{resize:vertical;min-height:232px;border:0;padding:0;background:transparent;line-height:1.9;font-size:12px}.lyrics-editor textarea:focus{outline:0}.lyrics-editor:focus-within{border-color:#698975}.editor-footer{display:flex;justify-content:space-between;gap:5px;color:#728377;font-size:9px;margin-top:12px;padding-top:14px;border-top:1px solid var(--line)}summary{cursor:pointer;font-size:12px;list-style-position:outside}summary::marker{color:#718579}summary #stamp-count{float:right;margin:2px 0 0;color:var(--muted);font-size:10px}.timings-panel[open] summary{margin-bottom:16px}.timeline-tools{display:flex;gap:6px}.timeline-tools button{font-size:9px;padding:6px 8px}.timeline{max-height:230px;overflow:auto;margin:14px 0}.timeline-row{display:flex;align-items:center;gap:8px;border-bottom:1px solid var(--line);padding:7px 0}.timeline-row span{flex:1;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.timeline-row input{width:78px;font-size:10px;margin:0;padding:5px}.timeline-row button{border:0;padding:4px;background:none}.preview-toolbar{display:flex;justify-content:space-between;align-items:center;margin:0 1px 13px;font-size:10px;color:var(--muted);letter-spacing:1.5px}.performance{background:#050706;border:1px solid var(--line);border-radius:7px;padding:23px 26px 15px;position:relative;min-height:421px;display:flex;flex-direction:column}.performance-top{display:flex;justify-content:space-between;gap:10px;font-size:9px;color:#74837a;letter-spacing:1px}.performance-top #mode-label{color:var(--accent)}.performance-body{display:grid;grid-template-columns:minmax(130px,34%) minmax(0,1fr);gap:30px;margin:31px 0 24px;min-height:214px;flex:1}.meta-label{display:block;font-size:8px;color:#64776a;letter-spacing:1.7px;margin-bottom:8px}.track-meta h2{font:500 21px/1.35 system-ui,sans-serif;overflow-wrap:anywhere;margin:0 0 25px}.track-meta p{font-size:10px;color:#9aa99f;overflow-wrap:anywhere;margin:0 0 23px}.lyric-preview{position:relative;overflow:auto;max-height:300px;scrollbar-width:thin;scrollbar-color:#304237 transparent;padding:0 10px 26px 0}.lyric-row{display:flex;align-items:baseline;gap:14px;width:100%;border:0;background:none;border-radius:0;text-align:left;white-space:normal;padding:6px 0;font:14px/1.65 system-ui,sans-serif;color:#87938b}.lyric-row:hover:not(:disabled){background:none;border:0;color:#e5ede8}.lyric-row small{width:15px;flex-shrink:0;font:8px monospace;color:#43574a}.lyric-row.active{color:var(--accent)}.lyric-row.section{font:9px/1.8 monospace;color:#657b6b;letter-spacing:1.2px;margin-top:10px;cursor:default}.lyric-row.pending{color:var(--red)}.lyric-row.recorded small{color:var(--accent)}.empty-state{padding:18px 0;color:#86988c}.empty-state>span{font-size:28px;color:#385641}.empty-state p{font-size:13px;margin:16px 0 7px}.empty-state small{font:10px/1.7 monospace;color:#5f7566}#spectrum{width:100%;height:64px;display:block;opacity:.9}.player-wrap{margin-top:20px}audio{width:100%;height:35px;display:block;filter:contrast(.9)}.sync-panel{margin-top:16px;border:1px solid var(--line);border-radius:6px;padding:20px 22px;background:#141b17}.sync-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{font-size:9px;color:var(--accent);letter-spacing:1.4px}.sync-header p{font-size:11px;margin:5px 0 0;color:var(--muted)}.sync-header button{font-size:11px}.sync-controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:20px}.stamp-button{flex:1;text-align:left;background:#222e25;border-color:#55795f;min-width:150px}.stamp-button kbd{float:right}.shortcuts{display:flex;flex-wrap:wrap;gap:12px;margin-top:19px;border-top:1px solid #28382d;padding-top:13px;font-size:9px;color:#788c7e}kbd{padding:1px 4px;border:1px solid #394f40;border-radius:3px;font:9px monospace;color:#a4bdac}.status{display:flex;align-items:center;margin:16px 2px;font-size:10px;color:var(--muted);min-height:22px;overflow-wrap:anywhere}.status i{flex-shrink:0;background:#4d6b56}.status.error{color:var(--red)}.status.error i{background:var(--red)}.page-footer{margin:0 3.8%;padding:18px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:#84958a;font-size:10px}.subtle{color:#52695a;margin-left:12px}.muted{color:var(--muted)}.small{font-size:11px}dialog{background:#141c17;color:var(--text);border:1px solid #3a5140;border-radius:9px;padding:25px;width:min(500px,95vw);max-height:88vh}dialog::backdrop{background:#020504cc;backdrop-filter:blur(4px)}.dialog-header{display:flex;align-items:center;justify-content:space-between}.dialog-header h2{font-size:17px;margin:0}.dialog-header button{background:none;border:0;font-size:23px;padding:0 4px;color:var(--muted)}dialog p{line-height:1.8}dialog label{margin:20px 0}dialog select{font-size:12px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}progress{width:100%;accent-color:var(--accent)}#video-status{font-size:11px;min-height:20px}#about-dialog pre{white-space:pre-wrap;font-size:10px;max-height:35vh;overflow:auto}.sr-only{position:absolute;overflow:hidden;clip:rect(0,0,0,0);width:1px;height:1px}.performance:fullscreen{width:100vw;height:100vh;padding:4vh 5vw;border:0;border-radius:0}.performance:fullscreen .performance-body{min-height:0;align-items:center}.performance:fullscreen .lyric-preview{max-height:65vh}.performance:fullscreen .lyric-row{font-size:clamp(18px,2.2vw,36px)}.performance:fullscreen .lyric-row.section{font-size:14px}.performance:fullscreen .track-meta h2{font-size:clamp(25px,3vw,45px)}.performance:fullscreen #spectrum{height:13vh}
@media(min-width:1400px){.performance{min-height:500px}.performance-body{margin-top:45px}.lyric-preview{max-height:360px}.lyrics-editor textarea{min-height:270px}}
@media(max-width:900px){.topbar{align-items:flex-start;flex-direction:column;gap:18px}.topbar nav{width:100%;flex-wrap:wrap}.workbench{grid-template-columns:280px minmax(0,1fr);gap:16px}.panel{padding:15px}.performance{padding:18px}.performance-body{grid-template-columns:1fr;gap:12px;margin-top:20px}.track-meta .meta-label:not(:first-child),.track-meta p{display:none}.track-meta h2{margin-bottom:4px}.lyric-preview{max-height:255px}.sync-panel{padding:15px}.sync-header{align-items:flex-start}.shortcuts span:last-child{display:none}}
@media(max-width:650px){main{padding-top:18px}.workbench{display:flex;flex-direction:column}.editor{display:grid;grid-template-columns:1fr;gap:12px}.lyrics-editor textarea{min-height:160px}.performance{min-height:390px}.performance-body{grid-template-columns:30% minmax(0,1fr);gap:20px;min-height:170px}.track-meta h2{font-size:17px}.track-meta .meta-label:not(:first-child),.track-meta p{display:block}.lyric-row{font-size:13px}.workspace-heading{font-size:8px;letter-spacing:.6px}.page-footer .subtle{display:none}nav button{font-size:10px;padding:8px 9px}.status{font-size:9px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}""")
            ]
        ]
        body [] [
            header [ _class "topbar" ] [
                a [ _class "wordmark"; _href "#"; attr "aria-label" "studio home" ] [
                    span [ _class "mark" ] [
                        str "▥"
                    ]
                    str "studio"
                    span [ _class "version" ] [
                        str "/ 01"
                    ]
                ]
                nav [ attr "aria-label" "Project" ] [
                    button [ _id "open-project" ] [
                        str "Open project"
                    ]
                    button [ _id "save-project"; attr "disabled" "" ] [
                        str "Save project"
                    ]
                    button [ _id "html-export"; _class "primary"; attr "disabled" "" ] [
                        str "Export HTML"
                        span [] [
                            str "↗"
                        ]
                    ]
                    button [ _id "video-open"; attr "disabled" "" ] [
                        str "Export MP4"
                        span [] [
                            str "↗"
                        ]
                    ]
                ]
            ]
            main [] [
                div [ _class "workspace-heading" ] [
                    span [] [
                        i [] []
                        str "LOCAL WORKSPACE"
                    ]
                    span [ _id "session-info" ] [
                        str "No media loaded"
                    ]
                ]
                div [ _class "workbench" ] [
                    aside [ _class "editor" ] [
                        section [ _class "panel" ] [
                            div [ _class "section-heading" ] [
                                h1 [] [
                                    span [] [
                                        str "01"
                                    ]
                                    str "Source"
                                ]
                                span [ _id "media-size" ] [
                                    str "—"
                                ]
                            ]
                            label [ _class "dropzone"; _id "media-drop"; attr "for" "media-file" ] [
                                span [ _class "upload-icon" ] [
                                    str "↑"
                                ]
                                strong [ _id "media-name" ] [
                                    str "Drop audio or choose a file"
                                ]
                                small [] [
                                    str "FLAC · M4A · MP3 · WAV · video audio"
                                ]
                            ]
                            input [ _type "file"; _id "media-file"; attr "accept" "audio/*,video/*,.flac,.m4a,.mp3,.wav,.aiff,.aif,.ogg,.opus,.aac"; _class "file-input" ]
                            div [ _class "title-row" ] [
                                label [] [
                                    str "Title"
                                    input [ _id "track-title"; attr "placeholder" "Untitled"; attr "maxlength" "2000" ]
                                ]
                                label [ _class "accent-label" ] [
                                    str "Accent"
                                    input [ _type "color"; _id "accent"; attr "value" "#90efb8" ]
                                ]
                            ]
                        ]
                        section [ _class "panel lyrics-editor" ] [
                            div [ _class "section-heading" ] [
                                h2 [] [
                                    span [] [
                                        str "02"
                                    ]
                                    str "Lyrics"
                                ]
                                button [ _id "lyrics-open"; _class "text-button" ] [
                                    str "Import .md ↗"
                                ]
                            ]
                            label [ _class "sr-only"; attr "for" "lyrics" ] [
                                str "Lyrics"
                            ]
                            tag "textarea" [ _id "lyrics"; attr "placeholder" "[Verse 1]\nOne line at a time\nAs the words arrive"; attr "spellcheck" "false" ] []
                            div [ _class "editor-footer" ] [
                                span [ _id "line-count" ] [
                                    str "0 lines"
                                ]
                                span [] [
                                    str "Blank lines are ignored"
                                ]
                            ]
                            input [ _type "file"; _id "lyrics-file"; attr "accept" ".md,.txt,.lrc,text/plain,text/markdown"; _class "file-input" ]
                        ]
                        details [ _class "panel timings-panel"; _id "timings-panel" ] [
                            summary [] [
                                span [] [
                                    str "03"
                                ]
                                str "Timeline"
                                span [ _id "stamp-count" ] [
                                    str "0 timed"
                                ]
                            ]
                            div [ _class "timeline-tools" ] [
                                button [ _id "timing-import" ] [
                                    str "Import JSON"
                                ]
                                button [ _id "timing-export"; attr "disabled" "" ] [
                                    str "Export JSON"
                                ]
                                button [ _id "lrc-export"; attr "disabled" "" ] [
                                    str "LRC"
                                ]
                            ]
                            div [ _id "timeline"; _class "timeline" ] [
                                p [ _class "muted" ] [
                                    str "Mark lyrics to build a timeline."
                                ]
                            ]
                            button [ _id "clear-timings"; _class "text-button"; attr "disabled" "" ] [
                                str "Clear timestamps"
                            ]
                            input [ _type "file"; _id "timing-file"; attr "accept" ".json,application/json"; _class "file-input" ]
                        ]
                    ]
                    section [ _class "preview-area" ] [
                        div [ _class "preview-toolbar" ] [
                            span [] [
                                str "PERFORMANCE"
                            ]
                            button [ _id "fullscreen"; _class "text-button" ] [
                                str "Fullscreen ⛶"
                            ]
                        ]
                        div [ _class "performance"; _id "performance" ] [
                            div [ _class "performance-top" ] [
                                span [ _id "mode-label" ] [
                                    str "PREVIEW"
                                ]
                                span [ _id "performance-clock" ] [
                                    str "00:00 / 00:00"
                                ]
                            ]
                            div [ _class "performance-body" ] [
                                div [ _class "track-meta" ] [
                                    span [ _class "meta-label" ] [
                                        str "TITLE"
                                    ]
                                    h2 [ _id "preview-title" ] [
                                        str "Untitled"
                                    ]
                                    span [ _class "meta-label" ] [
                                        str "SOURCE"
                                    ]
                                    p [ _id "preview-source" ] [
                                        str "—"
                                    ]
                                    span [ _class "meta-label" ] [
                                        str "TIMING"
                                    ]
                                    p [ _id "preview-timing" ] [
                                        str "Manual / not started"
                                    ]
                                ]
                                div [ _id "lyric-preview"; _class "lyric-preview" ] [
                                    div [ _class "empty-state" ] [
                                        span [] [
                                            str "∷"
                                        ]
                                        p [] [
                                            str "Your lyrics appear here."
                                        ]
                                        small [] [
                                            str "Load audio, add words, then mark each line."
                                        ]
                                    ]
                                ]
                            ]
                            canvas [ _id "spectrum"; attr "aria-label" "Audio spectrum" ] []
                            div [ _class "player-wrap" ] [
                                audio [ _id "player"; attr "controls" ""; attr "preload" "metadata" ] []
                            ]
                        ]
                        div [ _class "sync-panel" ] [
                            div [ _class "sync-header" ] [
                                div [] [
                                    span [ _class "eyebrow" ] [
                                        str "MANUAL SYNC"
                                    ]
                                    p [ _id "sync-instruction" ] [
                                        str "Mark the moment each lyric begins."
                                    ]
                                ]
                                button [ _id "sync-start"; attr "disabled" "" ] [
                                    str "Start timing"
                                ]
                            ]
                            div [ _id "sync-controls"; _class "sync-controls"; attr "hidden" "" ] [
                                button [ _id "stamp"; _class "stamp-button" ] [
                                    str "Mark line"
                                    kbd [] [
                                        str "Enter"
                                    ]
                                ]
                                button [ _id "undo"; attr "disabled" "" ] [
                                    str "Undo"
                                ]
                                button [ _id "sync-save"; _class "primary" ] [
                                    str "Save timing"
                                ]
                                button [ _id "sync-cancel" ] [
                                    str "Cancel"
                                ]
                            ]
                            div [ _class "shortcuts" ] [
                                span [] [
                                    kbd [] [
                                        str "Space"
                                    ]
                                    str "Play / pause"
                                ]
                                span [] [
                                    kbd [] [
                                        str "←"
                                    ]
                                    kbd [] [
                                        str "→"
                                    ]
                                    str "Seek 5s"
                                ]
                                span [] [
                                    str "Click a lyric to select or seek"
                                ]
                            ]
                        ]
                        div [ _class "status"; attr "role" "status"; attr "aria-live" "polite" ] [
                            i [ _id "status-dot" ] []
                            span [ _id "status-text" ] [
                                str "Ready. Files stay in this browser."
                            ]
                        ]
                    ]
                ]
            ]
            footer [ _class "page-footer" ] [
                span [] [
                    str "studio"
                    span [ _class "subtle" ] [
                        str "/ local audio + lyric timing"
                    ]
                ]
                button [ _id "about-open"; _class "text-button" ] [
                    str "Source & licenses"
                ]
            ]
            input [ _type "file"; _id "project-file"; attr "accept" ".studio.json,.json,application/json"; _class "file-input" ]
            dialog [ _id "video-dialog" ] [
                form [ attr "method" "dialog"; _class "dialog-header" ] [
                    h2 [] [
                        str "Export MP4"
                    ]
                    button [ attr "aria-label" "Close"; _id "video-close" ] [
                        str "×"
                    ]
                ]
                p [ _class "muted" ] [
                    str "Performance view · H.264 video + AAC audio · 30 fps"
                ]
                label [] [
                    str "Resolution"
                    select [ _id "video-resolution" ] [
                        option [ attr "value" "1280,720" ] [
                            str "1280 × 720 · landscape"
                        ]
                        option [ attr "value" "1920,1080" ] [
                            str "1920 × 1080 · landscape"
                        ]
                        option [ attr "value" "1080,1920" ] [
                            str "1080 × 1920 · portrait"
                        ]
                    ]
                ]
                p [ _class "small muted" ] [
                    str "Encoded locally, without playing or recording your screen. Large exports need sufficient browser memory. Native stem separation is not included."
                ]
                progress [ _id "video-progress"; attr "value" "0"; attr "max" "1"; attr "hidden" "" ] []
                p [ _id "video-status"; attr "role" "status" ] []
                div [ _class "dialog-actions" ] [
                    button [ _id "video-cancel"; attr "hidden" "" ] [
                        str "Cancel export"
                    ]
                    button [ _id "video-export"; _class "primary" ] [
                        str "Export MP4"
                    ]
                ]
            ]
            dialog [ _id "about-dialog" ] [
                form [ attr "method" "dialog"; _class "dialog-header" ] [
                    h2 [] [
                        str "studio"
                    ]
                    button [ attr "aria-label" "Close" ] [
                        str "×"
                    ]
                ]
                p [] [
                    str "Standalone lyric studio derived from mm-tools Yue2. The HTML player builder is unmodified. Stem separation in the original requires Python models and is not included here."
                ]
                p [] [
                    str "All processing is local. No uploads, analytics, external fonts, or runtime downloads."
                ]
                button [ _id "source-download" ] [
                    str "Download corresponding source"
                ]
                details [] [
                    summary [] [
                        str "Licenses and provenance"
                    ]
                    pre [ _id "licenses" ] [
                        str "STUDIO_LICENSES"
                    ]
                ]
