            script [ _id "studio-source"; _type "application/json" ] [ rawText ("""{"format":"studio-source","version":1,"files":{"src/vendor/yue-player.js":"// Unmodified functions from CommanderTurtle/mm-tools @ 789efc7778e4c05a948bffb3c96ea91c03844c44\n// music/yue2/local_app/web/app.js — AGPL-3.0-only.\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\")\n    .replaceAll(\"&\", \"&amp;\")\n    .replaceAll(\"\u003c\", \"&lt;\")\n    .replaceAll(\">\", \"&gt;\")\n    .replaceAll('\"', \"&quot;\")\n    .replaceAll(\"'\", \"&#039;\");\n}\n\nfunction hexToRgb(value) {\n  const hex = String(value || \"#90efb8\").replace(\"#\", \"\");\n  const full = hex.length === 3 ? [...hex].map((x) => x + x).join(\"\") : hex;\n  const parsed = Number.parseInt(full, 16);\n  if (!Number.isFinite(parsed)) return \"144, 239, 184\";\n  return `${(parsed >> 16) & 255}, ${(parsed >> 8) & 255}, ${parsed & 255}`;\n}\n\nfunction buildAudioPlayerHtml({ title, source, accent, lyrics, timestamps }) {\n  const accentRgb = hexToRgb(accent);\n  const rows = lyrics.map((line) => '\u003cp' + (/^\\[.+\\]$/.test(line) ? ' class=\"section\" data-section=\"1\"' : \"\") + \">\" + escapeHtml(line) + \"\u003c/p>\").join(\"\\n    \");\n  const css = [\n    \":root{--accent:\" + accent + \";--pulse:0}\",\n    \"*{box-sizing:border-box}\",\n    \"html,body{margin:0;min-height:100%}\",\n    \"body{display:grid;place-items:center;padding:28px 20px;background:radial-gradient(120% 90% at 50% 0%,#101513 0%,#070908 60%);color:#e9eeeb;font:14px/1.55 system-ui,-apple-system,'Segoe UI',sans-serif}\",\n    \"main{position:relative;width:min(880px,100%);border:1px solid rgba(\" + accentRgb + \",.16);border-radius:16px;background:linear-gradient(150deg,rgba(\" + accentRgb + \",.07),transparent 52%),#0e1110;padding:26px 26px 16px;overflow:hidden}\",\n    \"h1{margin:0;font-size:19px;font-weight:650;letter-spacing:-.01em}\",\n    \".source{margin:6px 0 0}\",\n    \".source a{display:inline-block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#98a29c;font:11px ui-monospace,SFMono-Regular,Menlo,monospace;text-decoration:none;border-bottom:1px dotted rgba(152,162,156,.4)}\",\n    \".source a:hover{color:var(--accent)}\",\n    \".stage{position:relative;margin-top:20px}\",\n    \".orbit{position:absolute;top:-42%;left:12%;width:76%;aspect-ratio:1;border:1px solid rgba(\" + accentRgb + \",.18);border-radius:50%;box-shadow:0 0 70px rgba(\" + accentRgb + \",calc(.1 + var(--pulse) * .22)),inset 0 0 50px rgba(\" + accentRgb + \",calc(.05 + var(--pulse) * .08));opacity:calc(.5 + var(--pulse) * .5);transform:scale(calc(1 + var(--pulse) * .05));pointer-events:none}\",\n    \"canvas{display:block;width:100%;height:170px;opacity:.92}\",\n    \".lyrics{position:relative;max-height:190px;overflow:auto;margin-top:14px;padding:14px 4px 6px;-webkit-mask-image:linear-gradient(transparent,black 14%,black 86%,transparent);mask-image:linear-gradient(transparent,black 14%,black 86%,transparent);scrollbar-width:thin;scrollbar-color:rgba(\" + accentRgb + \",.35) transparent;text-align:center}\",\n    \".lyrics p{margin:4px 0;color:#98a29c;font:12px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;transition:color .2s ease,transform .2s ease,font-size .2s ease}\",\n    \".lyrics p.section{margin-top:12px;color:rgba(\" + accentRgb + \",.6);font-size:10px;letter-spacing:.14em;text-transform:uppercase}\",\n    \".lyrics p.active{color:#e9eeeb;font-size:14px;transform:translateX(10px)}\",\n    \"audio{display:block;width:100%;margin-top:16px}\",\n    \"footer{display:flex;justify-content:space-between;gap:12px;margin-top:10px;color:#98a29c;font:10px ui-monospace,monospace;letter-spacing:.1em}\",\n  ].join(\"\\n\");\n  const script = [\n    '\"use strict\";',\n    \"(() => {\",\n    \"  var $ = function (id) { return document.getElementById(id); };\",\n    \"  var audio = $(\\\"player\\\");\",\n    \"  var canvas = $(\\\"spectrum\\\");\",\n    \"  var clock = $(\\\"clock\\\");\",\n    \"  var rows = Array.prototype.slice.call(document.querySelectorAll(\\\".lyrics p\\\"));\",\n    \"  var candidates = rows.filter(function (row) { return row.dataset.section !== \\\"1\\\"; });\",\n    \"  var times = (function () {\",\n    \"    var map = {};\",\n    \"    var data = \" + JSON.stringify(Array.isArray(timestamps) ? timestamps : []) + \";\",\n    \"    for (var i = 0; i \u003c data.length; i += 1) {\",\n    \"      if (data[i] && isFinite(Number(data[i].start))) map[Number(data[i].line)] = Number(data[i].start);\",\n    \"    }\",\n    \"    return map;\",\n    \"  })();\",\n    \"  var context = null;\",\n    \"  var analyser = null;\",\n    \"  var animation = 0;\",\n    \"  var activeIndex = -1;\",\n    \"  var ACCENT = \\\"\" + accent + \"\\\";\",\n    \"  function formatTime(seconds) {\",\n    \"    if (!isFinite(seconds)) return \\\"00:00\\\";\",\n    \"    var whole = Math.max(0, Math.floor(seconds));\",\n    \"    var m = Math.floor(whole / 60);\",\n    \"    var s = whole % 60;\",\n    \"    return (m \u003c 10 ? \\\"0\\\" + m : m) + \\\":\\\" + (s \u003c 10 ? \\\"0\\\" + s : s);\",\n    \"  }\",\n    \"  function paint() {\",\n    \"    var ratio = Math.min(window.devicePixelRatio || 1, 2);\",\n    \"    var width = Math.max(canvas.clientWidth, 1);\",\n    \"    var height = Math.max(canvas.clientHeight, 1);\",\n    \"    if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) { canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio); }\",\n    \"    var draw = canvas.getContext(\\\"2d\\\");\",\n    \"    draw.setTransform(ratio, 0, 0, ratio, 0, 0);\",\n    \"    draw.clearRect(0, 0, width, height);\",\n    \"    var bins = new Uint8Array(analyser ? analyser.frequencyBinCount : 64);\",\n    \"    if (analyser) analyser.getByteFrequencyData(bins);\",\n    \"    var lowCount = Math.min(8, bins.length);\",\n    \"    var low = 0;\",\n    \"    for (var i = 0; i \u003c lowCount; i += 1) low += bins[i];\",\n    \"    low = lowCount ? low / lowCount : 0;\",\n    \"    document.documentElement.style.setProperty(\\\"--pulse\\\", String(Math.min(1, low / 80)));\",\n    \"    var count = 46;\",\n    \"    var gap = 3;\",\n    \"    var bar = Math.max(2, (width - gap * (count - 1)) / count);\",\n    \"    for (var index = 0; index \u003c count; index += 1) {\",\n    \"      var sample = bins[Math.floor((index / count) * bins.length)] || (audio.paused ? 18 + Math.sin(index * 0.65) * 9 : 0);\",\n    \"      var level = Math.max(3, (sample / 255) * (height - 8));\",\n    \"      var x = index * (bar + gap);\",\n    \"      var y = height - level;\",\n    \"      var gradient = draw.createLinearGradient(0, y, 0, height);\",\n    \"      gradient.addColorStop(0, ACCENT);\",\n    \"      gradient.addColorStop(1, ACCENT + \\\"33\\\");\",\n    \"      draw.fillStyle = gradient;\",\n    \"      draw.beginPath();\",\n    \"      if (draw.roundRect) draw.roundRect(x, y, bar, level, Math.min(bar / 2, 3)); else draw.rect(x, y, bar, level);\",\n    \"      draw.fill();\",\n    \"    }\",\n    \"    if (!audio.paused && !audio.ended) animation = requestAnimationFrame(paint);\",\n    \"  }\",\n    \"  function syncLyrics() {\",\n    \"    if (!candidates.length || !isFinite(audio.duration) || audio.duration \u003c= 0) return;\",\n    \"    var known = Object.keys(times).length > 0;\",\n    \"    var selected = null;\",\n    \"    if (known) {\",\n    \"      for (var k = 0; k \u003c candidates.length; k += 1) {\",\n    \"        var rowIndex = rows.indexOf(candidates[k]);\",\n    \"        if (times[rowIndex] != null && times[rowIndex] \u003c= audio.currentTime + 0.15) selected = candidates[k];\",\n    \"      }\",\n    \"    } else {\",\n    \"      selected = candidates[Math.min(candidates.length - 1, Math.floor((audio.currentTime / audio.duration) * candidates.length))];\",\n    \"    }\",\n    \"    if (!selected) return;\",\n    \"    var index = rows.indexOf(selected);\",\n    \"    if (index === activeIndex) return;\",\n    \"    activeIndex = index;\",\n    \"    rows.forEach(function (row, i) { row.classList.toggle(\\\"active\\\", i === index); });\",\n    \"    var panel = selected.parentElement;\",\n    \"    panel.scrollTo({ top: Math.max(0, selected.offsetTop - panel.clientHeight / 2), behavior: \\\"smooth\\\" });\",\n    \"  }\",\n    \"  audio.addEventListener(\\\"play\\\", async function () {\",\n    \"    var AudioContextType = window.AudioContext || window.webkitAudioContext;\",\n    \"    if (!AudioContextType) return;\",\n    \"    if (!context) {\",\n    \"      context = new AudioContextType();\",\n    \"      analyser = context.createAnalyser();\",\n    \"      analyser.fftSize = 256;\",\n    \"      analyser.smoothingTimeConstant = 0.84;\",\n    \"      var node = context.createMediaElementSource(audio);\",\n    \"      node.connect(analyser);\",\n    \"      analyser.connect(context.destination);\",\n    \"    }\",\n    \"    await context.resume();\",\n    \"    cancelAnimationFrame(animation);\",\n    \"    paint();\",\n    \"  });\",\n    \"  audio.addEventListener(\\\"pause\\\", function () { cancelAnimationFrame(animation); paint(); });\",\n    \"  audio.addEventListener(\\\"ended\\\", function () { cancelAnimationFrame(animation); paint(); });\",\n    \"  audio.addEventListener(\\\"timeupdate\\\", function () {\",\n    \"    clock.textContent = formatTime(audio.currentTime) + \\\" / \\\" + formatTime(audio.duration);\",\n    \"    syncLyrics();\",\n    \"  });\",\n    \"  requestAnimationFrame(paint);\",\n    \"})();\",\n  ].join(\"\\n\");\n  return [\n    \"\u003c!doctype html>\",\n    '\u003chtml lang=\"en\">',\n    \"\u003chead>\",\n    '\u003cmeta charset=\"utf-8\">',\n    '\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">',\n    \"\u003ctitle>\" + escapeHtml(title) + \"\u003c/title>\",\n    \"\u003cstyle>\",\n    css,\n    \"\u003c/style>\",\n    \"\u003c/head>\",\n    \"\u003cbody>\",\n    \"\u003cmain>\",\n    \"\u003ch1>\" + escapeHtml(title) + \"\u003c/h1>\",\n    '\u003cp class=\"source\">\u003ca href=\"' + escapeHtml(source) + '\" target=\"_blank\" rel=\"noopener\">' + escapeHtml(source) + \"\u003c/a>\u003c/p>\",\n    '\u003cdiv class=\"stage\">\u003cdiv class=\"orbit\">\u003c/div>\u003ccanvas id=\"spectrum\" aria-label=\"Live audio spectrum\">\u003c/canvas>\u003c/div>',\n    (lyrics.length ? '\u003csection class=\"lyrics\">\\n    ' + rows + \"\\n\u003c/section>\" : \"\"),\n    '\u003caudio id=\"player\" src=\"' + escapeHtml(source) + '\" crossorigin=\"anonymous\" controls preload=\"metadata\">\u003c/audio>',\n    '\u003cfooter>\u003cspan>SELF-CONTAINED PLAYER &middot; MM-TOOLS\u003c/span>\u003ctime id=\"clock\">00:00 / 00:00\u003c/time>\u003c/footer>',\n    \"\u003c/main>\",\n    \"\u003cscript>\",\n    script,\n    \"\u003c/scr\" + \"ipt>\",\n    \"\u003c/body>\",\n    \"\u003c/html>\",\n  ].join(\"\\n\");\n}\n\nfunction audioBufferToWav(buffer) {\n  const channels = Math.min(2, buffer.numberOfChannels);\n  const frames = buffer.length;\n  const bytesPerSample = 2;\n  const dataSize = frames * channels * bytesPerSample;\n  const arrayBuffer = new ArrayBuffer(44 + dataSize);\n  const view = new DataView(arrayBuffer);\n  const writeString = (offset, text) => { for (let i = 0; i \u003c text.length; i += 1) view.setUint8(offset + i, text.charCodeAt(i)); };\n  writeString(0, \"RIFF\"); view.setUint32(4, 36 + dataSize, true); writeString(8, \"WAVE\");\n  writeString(12, \"fmt \"); view.setUint32(16, 16, true); view.setUint16(20, 1, true);\n  view.setUint16(22, channels, true); view.setUint32(24, buffer.sampleRate, true);\n  view.setUint32(28, buffer.sampleRate * channels * bytesPerSample, true);\n  view.setUint16(32, channels * bytesPerSample, true); view.setUint16(34, 16, true);\n  writeString(36, \"data\"); view.setUint32(40, dataSize, true);\n  let offset = 44;\n  const channelData = [...Array(channels)].map((_, channel) => buffer.getChannelData(channel));\n  for (let frame = 0; frame \u003c frames; frame += 1) {\n    for (let channel = 0; channel \u003c channels; channel += 1) {\n      const sample = Math.max(-1, Math.min(1, channelData[channel][frame]));\n      view.setInt16(offset, sample \u003c 0 ? sample * 0x8000 : sample * 0x7fff, true);\n      offset += 2;\n    }\n  }\n  return new Uint8Array(arrayBuffer);\n}\n\nexport { escapeHtml, hexToRgb, buildAudioPlayerHtml, audioBufferToWav };\n","src/vendor/upstream.json":"{\n  \"repository\": \"https://github.com/CommanderTurtle/mm-tools\",\n  \"revision\": \"789efc7778e4c05a948bffb3c96ea91c03844c44\",\n  \"file\": \"music/yue2/local_app/web/app.js\",\n  \"functions\": [\n    {\n      \"name\": \"escapeHtml\",\n      \"sha256\": \"5730a6d1f3d54b2ad7f4b42cf997d4180358fafadee32e02d810e396194863d5\"\n    },\n    {\n      \"name\": \"hexToRgb\",\n      \"sha256\": \"55f63326e0675339d6c6aaaa544ab17aaf3908f086344614552fa28010ddbb98\"\n    },\n    {\n      \"name\": \"buildAudioPlayerHtml\",\n      \"sha256\": \"6921ad695418ad26c02927c2bf9024e7782f76503ce2d1d11b00780870f205dc\"\n    },\n    {\n      \"name\": \"audioBufferToWav\",\n      \"sha256\": \"fdeff6c56a463c28c3d96182a446cfd1e1aa679793ee362dc621b24206965500\"\n    }\n  ]\n}\n","src/core.js":"export const parseLyrics = text => String(text ?? '').split(/\\r?\\n/).map(line => line.trim()).filter(Boolean);\nexport const isSection = line => /^\\[.+\\]$/.test(line);\nexport const lyricIndices = lines => lines.flatMap((line, index) => isSection(line) ? [] : [index]);\nexport const formatTime = seconds => {\n  const value = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;\n  return `${String(Math.floor(value / 60)).padStart(2, '0')}:${String(Math.floor(value % 60)).padStart(2, '0')}`;\n};\nexport const safeFilename = title => (title || 'studio').replace(/[\u003c>:\"/\\\\|?*\\x00-\\x1f]/g, '_').replace(/[. ]+$/, '').slice(0, 140) || 'studio';\nexport const validAccent = value => /^#[\\da-f]{6}$/i.test(value) ? value : '#90efb8';\n\n// Keep the Yue row-index contract, including section headings in the row count.\n// Construct fresh numeric records: project data must never reach the HTML script verbatim.\nexport function validateTimestamps(raw, lines, duration = Infinity) {\n  if (!Array.isArray(raw)) throw Error('Timestamps must be an array.');\n  const seen = new Set();\n  const stamps = raw.map(record => {\n    const line = record?.line, start = record?.start;\n    if (!Number.isInteger(line) || line \u003c 0 || line >= lines.length || isSection(lines[line])) {\n      throw Error('A timestamp refers to a missing lyric or section heading.');\n    }\n    if (typeof start !== 'number' || !Number.isFinite(start) || start \u003c 0 || start > duration + 0.05) {\n      throw Error('Timestamp seconds must be within the audio duration.');\n    }\n    if (seen.has(line)) throw Error('Each lyric can have only one timestamp.');\n    seen.add(line);\n    return { line, start: Math.round(start * 1000) / 1000 };\n  }).sort((a, b) => a.line - b.line);\n  for (let i = 1; i \u003c stamps.length; i++) {\n    if (stamps[i].start \u003c stamps[i - 1].start) throw Error('Lyric timestamps must run in order.');\n  }\n  return stamps;\n}\n\nexport function activeLine(lines, stamps, time, duration) {\n  const candidates = lyricIndices(lines);\n  if (!candidates.length || !(duration > 0)) return -1;\n  if (!stamps.length) return candidates[Math.min(candidates.length - 1, Math.floor(Math.max(0, time) / duration * candidates.length))];\n  let selected = -1;\n  for (const stamp of stamps) if (stamp.start \u003c= time + 0.15) selected = stamp.line;\n  return selected;\n}\n\nexport function remapTimestamps(oldLines, newLines, stamps) {\n  const occurrences = new Map();\n  for (const stamp of stamps) {\n    const text = oldLines[stamp.line];\n    if (!occurrences.has(text)) occurrences.set(text, []);\n  }\n  const byLine = new Map(stamps.map(stamp => [stamp.line, stamp.start]));\n  oldLines.forEach((text, line) => {\n    if (occurrences.has(text)) occurrences.get(text).push(byLine.get(line));\n  });\n  const offsets = new Map();\n  const next = [];\n  newLines.forEach((text, line) => {\n    const occurrence = offsets.get(text) || 0;\n    offsets.set(text, occurrence + 1);\n    const start = occurrences.get(text)?.[occurrence];\n    if (start !== undefined && !isSection(text)) next.push({ line, start });\n  });\n  // Reordering lyrics must not silently apply an out-of-order timeline.\n  return next.filter((stamp, index) => !next.slice(0, index).some(previous => previous.start > stamp.start));\n}\n\nexport function readProject(raw) {\n  if (raw?.format !== 'studio' || raw.version !== 1) throw Error('Not a studio project (version 1).');\n  if (typeof raw.lyrics !== 'string' || typeof raw.title !== 'string') throw Error('Project text is missing.');\n  if (raw.lyrics.length > 2_000_000 || raw.title.length > 2000) throw Error('Project text is too large.');\n  if (typeof raw.media?.data !== 'string' || !/^data:(?:audio|video|application\\/octet-stream)[^,]*;base64,[a-z\\d+/=\\r\\n]+$/i.test(raw.media.data)) {\n    throw Error('The project must contain embedded audio or video, not an external URL.');\n  }\n  const lines = parseLyrics(raw.lyrics);\n  return { title: raw.title, accent: validAccent(raw.accent), lyrics: raw.lyrics, lines,\n    timestamps: validateTimestamps(raw.lyric_timestamps, lines),\n    media: { data: raw.media.data, name: String(raw.media.name || 'audio') } };\n}\n\nexport function toLrc(lines, timestamps) {\n  return timestamps.map(({ line, start }) => {\n    const centiseconds = Math.round(start * 100);\n    const minutes = Math.floor(centiseconds / 6000), seconds = ((centiseconds % 6000) / 100).toFixed(2).padStart(5, '0');\n    return `[${String(minutes).padStart(2, '0')}:${seconds}]${lines[line]}`;\n  }).join('\\n') + '\\n';\n}\n","src/app.js":"import { parseLyrics, lyricIndices, isSection, activeLine, formatTime, validAccent, safeFilename, validateTimestamps, remapTimestamps, readProject, toLrc } from './core.js';\nimport { buildAudioPlayerHtml } from './vendor/yue-player.js';\nimport { drawBars } from './render.js';\nimport { exportMp4 } from './video.js';\n\nconst $ = id => document.getElementById(id);\nconst state = { file: null, buffer: null, url: null, data: null, lines: [], timestamps: [],\n  draft: null, target: -1, history: [], busy: false, abort: null };\nconst player = $('player');\nlet context, analyser, animation, selected = -2;\nfunction status(message, error = false) {\n  $('status-text').textContent = message;\n  $('status-text').parentElement.classList.toggle('error', error);\n}\nfunction fail(error) { console.error(error); status(error.message || String(error), true); }\nfunction audioContext() {\n  const AudioContextType = window.AudioContext || window.webkitAudioContext;\n  if (!AudioContextType) throw Error('This browser does not support Web Audio.');\n  return context ||= new AudioContextType();\n}\nfunction projectSnapshot() {\n  return { title: $('track-title').value || 'Untitled', accent: validAccent($('accent').value),\n    lines: [...state.lines], timestamps: validateTimestamps(state.timestamps, state.lines, state.buffer.duration) };\n}\nfunction updateControls() {\n  const ready = Boolean(state.buffer) && !state.busy, manual = Boolean(state.draft);\n  for (const id of ['save-project', 'html-export', 'video-open']) $(id).disabled = !ready || manual;\n  $('sync-start').disabled = !ready || !lyricIndices(state.lines).length;\n  $('sync-start').hidden = manual; $('sync-controls').hidden = !manual;\n  $('stamp').disabled = !ready || state.target \u003c 0;\n  $('undo').disabled = state.busy || !state.history.length;\n  $('sync-save').disabled = state.busy;\n  for (const id of ['timing-export', 'lrc-export', 'clear-timings']) $(id).disabled = state.busy || manual || !state.timestamps.length;\n  for (const id of ['lyrics', 'track-title', 'accent', 'media-file', 'open-project', 'lyrics-open', 'timing-import']) $(id).disabled = state.busy || (manual && id !== 'track-title' && id !== 'accent');\n  $('mode-label').textContent = manual ? 'MANUAL SYNC / REC' : 'PREVIEW';\n  $('line-count').textContent = `${lyricIndices(state.lines).length} lines`;\n  $('stamp-count').textContent = `${state.timestamps.length} timed`;\n  $('preview-timing').textContent = manual ? 'Manual / recording' : state.timestamps.length ? `Manual / ${state.timestamps.length} lines` : 'Manual / not started';\n  $('sync-instruction').textContent = manual\n    ? state.target \u003c 0 ? 'All lines marked. Save timing to commit.' : `Next: ${state.lines[state.target]}`\n    : 'Mark the moment each lyric begins.';\n  for (const control of $('timeline').querySelectorAll('input,button')) control.disabled = state.busy || manual;\n}\nfunction setBusy(busy) { state.busy = busy; updateControls(); }\n\nfunction rebuildLyrics() {\n  const panel = $('lyric-preview'); panel.replaceChildren();\n  if (!state.lines.length) {\n    const empty = document.createElement('div'); empty.className = 'empty-state';\n    const icon = document.createElement('span'); icon.textContent = '∷';\n    const text = document.createElement('p'); text.textContent = 'Your lyrics appear here.';\n    const small = document.createElement('small'); small.textContent = 'Load audio, add words, then mark each line.';\n    empty.append(icon, text, small); panel.append(empty);\n  }\n  state.lines.forEach((text, index) => {\n    const row = document.createElement(isSection(text) ? 'div' : 'button');\n    row.className = 'lyric-row' + (isSection(text) ? ' section' : ''); row.dataset.line = String(index);\n    const number = document.createElement('small'); number.textContent = isSection(text) ? '—' : String(index + 1).padStart(2, '0');\n    const content = document.createElement('span'); content.textContent = text; row.append(number, content);\n    if (!isSection(text)) row.addEventListener('click', () => {\n      if (state.busy) return;\n      if (state.draft) { state.target = index; updateControls(); syncLyrics(); }\n      else {\n        const stamp = state.timestamps.find(item => item.line === index);\n        if (stamp && state.buffer) player.currentTime = stamp.start;\n      }\n    });\n    panel.append(row);\n  });\n  selected = -2; syncLyrics(); updateControls(); rebuildTimeline();\n}\n\nfunction syncLyrics() {\n  const stamps = state.draft ? [...state.draft].map(([line, start]) => ({ line, start })).sort((a, b) => a.line - b.line) : state.timestamps;\n  const current = state.draft ? state.target : activeLine(state.lines, stamps, player.currentTime, state.buffer?.duration || 0);\n  for (const row of $('lyric-preview').querySelectorAll('[data-line]')) {\n    const line = Number(row.dataset.line);\n    row.classList.toggle('active', !state.draft && line === current);\n    row.classList.toggle('pending', Boolean(state.draft) && line === current);\n    row.classList.toggle('recorded', Boolean(state.draft?.has(line)));\n    if (line === current && current !== selected) {\n      const panel = $('lyric-preview');\n      panel.scrollTo({ top: Math.max(0, row.offsetTop - panel.clientHeight * 0.4), behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });\n    }\n  }\n  selected = current;\n  $('performance-clock').textContent = `${formatTime(player.currentTime)} / ${formatTime(state.buffer?.duration)}`;\n}\n\nfunction rebuildTimeline() {\n  const panel = $('timeline'); panel.replaceChildren();\n  if (!state.timestamps.length) {\n    const text = document.createElement('p'); text.className = 'muted'; text.textContent = 'Mark lyrics to build a timeline.'; panel.append(text);\n  }\n  for (const stamp of state.timestamps) {\n    const row = document.createElement('div'); row.className = 'timeline-row';\n    const text = document.createElement('span'); text.textContent = state.lines[stamp.line]; text.title = text.textContent;\n    const input = document.createElement('input'); input.type = 'number'; input.min = '0'; input.max = String(state.buffer?.duration || 0); input.step = '.001';\n    input.value = String(stamp.start); input.disabled = Boolean(state.draft) || state.busy; input.setAttribute('aria-label', `Start seconds: ${text.textContent}`);\n    input.addEventListener('change', () => {\n      try {\n        state.timestamps = validateTimestamps(state.timestamps.map(item => item.line === stamp.line ? { line: item.line, start: Number(input.value) } : item), state.lines, state.buffer.duration);\n        status('Timestamp updated.'); syncLyrics();\n      } catch (error) { input.value = String(state.timestamps.find(item => item.line === stamp.line).start); fail(error); }\n    });\n    const remove = document.createElement('button'); remove.textContent = '×'; remove.setAttribute('aria-label', `Remove timestamp: ${text.textContent}`);\n    remove.disabled = Boolean(state.draft) || state.busy;\n    remove.addEventListener('click', () => { state.timestamps = state.timestamps.filter(item => item.line !== stamp.line); rebuildTimeline(); updateControls(); syncLyrics(); });\n    row.append(text, input, remove); panel.append(row);\n  }\n}\n\nfunction paint() {\n  const canvas = $('spectrum'), ratio = Math.min(devicePixelRatio || 1, 2);\n  const width = canvas.clientWidth, height = canvas.clientHeight;\n  if (canvas.width !== Math.round(width * ratio) || canvas.height !== Math.round(height * ratio)) { canvas.width = Math.round(width * ratio); canvas.height = Math.round(height * ratio); }\n  const ctx = canvas.getContext('2d'); ctx.setTransform(ratio, 0, 0, ratio, 0, 0); ctx.clearRect(0, 0, width, height);\n  const bins = new Uint8Array(128); if (analyser) analyser.getByteFrequencyData(bins);\n  const levels = Float32Array.from(bins, sample => sample / 255);\n  drawBars(ctx, levels, width, height); syncLyrics();\n  if (!player.paused && !player.ended) animation = requestAnimationFrame(paint);\n}\nplayer.addEventListener('play', async () => {\n  try {\n    const ctx = audioContext();\n    if (!analyser) { analyser = ctx.createAnalyser(); analyser.fftSize = 256; analyser.smoothingTimeConstant = .82; ctx.createMediaElementSource(player).connect(analyser); analyser.connect(ctx.destination); }\n    await ctx.resume(); cancelAnimationFrame(animation); paint();\n  } catch (error) { fail(error); }\n});\nfor (const event of ['pause', 'ended', 'seeked', 'loadedmetadata']) player.addEventListener(event, () => { cancelAnimationFrame(animation); paint(); });\nplayer.addEventListener('timeupdate', syncLyrics);\nplayer.addEventListener('error', () => { if (state.file) status('This browser cannot play the selected media format. Try a WAV, MP3, FLAC or supported M4A file.', true); });\nnew ResizeObserver(() => { if (player.paused) paint(); }).observe($('spectrum'));\n\nasync function decodeFile(file) {\n  if (!file.size) throw Error('The media file is empty.');\n  try { return await audioContext().decodeAudioData(await file.arrayBuffer()); }\n  catch { throw Error('This browser cannot decode this media file. Try a WAV, MP3, FLAC or supported M4A file. No file was uploaded.'); }\n}\nfunction adoptMedia(file, buffer, { title, data = null } = {}) {\n  player.pause(); if (state.url) URL.revokeObjectURL(state.url);\n  state.file = file; state.buffer = buffer; state.data = data; state.url = URL.createObjectURL(file);\n  state.timestamps = []; state.draft = null; state.target = -1; state.history = [];\n  player.src = state.url;\n  $('track-title').value = title ?? file.name.replace(/\\.[^.]+$/, '');\n  $('media-name').textContent = file.name; $('media-size').textContent = (file.size / 1024 / 1024).toFixed(1) + ' MB';\n  $('preview-source').textContent = file.name;\n  $('session-info').textContent = `${formatTime(buffer.duration)} / ${Math.round(buffer.sampleRate / 100) / 10} kHz / ${buffer.numberOfChannels} ch`;\n  updateTitle();\n}\nasync function loadMedia(file) {\n  if (!file || state.busy || state.draft) return;\n  setBusy(true); status('Reading local media…');\n  try {\n    const buffer = await decodeFile(file); adoptMedia(file, buffer); rebuildLyrics();\n    status('Media loaded. Add lyrics, then start timing.');\n  } catch (error) { fail(error); }\n  finally { setBusy(false); $('media-file').value = ''; }\n}\n$('media-file').addEventListener('change', event => loadMedia(event.target.files[0]));\nconst drop = $('media-drop');\nfor (const event of ['dragenter', 'dragover']) drop.addEventListener(event, e => { e.preventDefault(); drop.classList.add('dragging'); });\nfor (const event of ['dragleave', 'drop']) drop.addEventListener(event, e => { e.preventDefault(); drop.classList.remove('dragging'); if (event === 'drop') loadMedia(e.dataTransfer.files[0]); });\nfunction updateTitle() {\n  $('preview-title').textContent = $('track-title').value || 'Untitled';\n  document.documentElement.style.setProperty('--accent', validAccent($('accent').value));\n}\n$('track-title').addEventListener('input', updateTitle); $('accent').addEventListener('input', updateTitle);\nfunction updateLyrics() {\n  const lines = parseLyrics($('lyrics').value); state.timestamps = remapTimestamps(state.lines, lines, state.timestamps); state.lines = lines; rebuildLyrics();\n}\n$('lyrics').addEventListener('input', updateLyrics);\n$('lyrics-open').addEventListener('click', () => $('lyrics-file').click());\n$('lyrics-file').addEventListener('change', async event => {\n  try {\n    const file = event.target.files[0]; if (!file || state.busy || state.draft) return;\n    if (file.size > 2_000_000) throw Error('Lyrics must be smaller than 2 MB.');\n    const text = await file.text();\n    // LRC import is optional; ordinary Markdown is kept as plain text.\n    if (/\\.lrc$/i.test(file.name)) {\n      const rows = text.split(/\\r?\\n/), lines = [], timestamps = [];\n      for (const row of rows) {\n        const match = row.match(/^\\[(\\d+):(\\d{2}(?:\\.\\d+)?)\\]\\s*(.+)$/);\n        if (match) { timestamps.push({ line: lines.length, start: Number(match[1]) * 60 + Number(match[2]) }); lines.push(match[3].trim()); }\n      }\n      if (!lines.length) throw Error('No timed lyrics found in the LRC file.');\n      const checked = validateTimestamps(timestamps, lines, state.buffer?.duration || Infinity);\n      $('lyrics').value = lines.join('\\n'); state.lines = lines; state.timestamps = checked; rebuildLyrics();\n    } else { $('lyrics').value = text; updateLyrics(); }\n    status('Lyrics imported.');\n  } catch (error) { fail(error); } finally { event.target.value = ''; }\n});\n\n$('sync-start').addEventListener('click', () => {\n  if (!state.buffer || state.busy) return;\n  state.draft = new Map(state.timestamps.map(item => [item.line, item.start])); state.history = [];\n  state.target = lyricIndices(state.lines).find(line => !state.draft.has(line)) ?? lyricIndices(state.lines)[0] ?? -1;\n  updateControls(); rebuildTimeline(); syncLyrics(); status('Timing started. Play the audio and mark each line with Enter.');\n});\nfunction stampLine() {\n  if (!state.draft || state.target \u003c 0 || state.busy) return;\n  const line = state.target, start = Math.round(player.currentTime * 1000) / 1000;\n  state.history.push({ line, previous: state.draft.get(line) }); state.draft.set(line, start);\n  state.target = lyricIndices(state.lines).find(index => index > line && !state.draft.has(index)) ?? -1;\n  updateControls(); syncLyrics();\n}\n$('stamp').addEventListener('click', stampLine);\n$('undo').addEventListener('click', () => {\n  const previous = state.history.pop(); if (!previous) return;\n  if (previous.previous === undefined) state.draft.delete(previous.line); else state.draft.set(previous.line, previous.previous);\n  state.target = previous.line; updateControls(); syncLyrics();\n});\n$('sync-save').addEventListener('click', () => {\n  try {\n    state.timestamps = validateTimestamps([...state.draft].map(([line, start]) => ({ line, start })), state.lines, state.buffer.duration);\n    state.draft = null; state.history = []; updateControls(); rebuildTimeline(); syncLyrics(); status('Timing saved. Export a player, video or project.');\n  } catch (error) { fail(error); }\n});\n$('sync-cancel').addEventListener('click', () => { state.draft = null; state.history = []; updateControls(); rebuildTimeline(); syncLyrics(); status('Draft timing discarded. Previous timestamps kept.'); });\n$('clear-timings').addEventListener('click', () => { if (confirm('Clear all saved timestamps?')) { state.timestamps = []; rebuildTimeline(); updateControls(); syncLyrics(); status('Timestamps cleared.'); } });\ndocument.addEventListener('keydown', event => {\n  // Native media controls already handle Space. Don't toggle playback twice.\n  if (event.repeat || event.altKey || event.ctrlKey || event.metaKey || state.busy || document.querySelector('dialog[open]') || event.target.closest('input,textarea,select,button,a,audio,video,[contenteditable]')) return;\n  if (event.code === 'Space' && state.buffer) { event.preventDefault(); if (player.paused) player.play().catch(fail); else player.pause(); }\n  if (event.key === 'Enter' && state.draft) { event.preventDefault(); stampLine(); }\n  if (['ArrowLeft', 'ArrowRight'].includes(event.key) && state.buffer) { event.preventDefault(); player.currentTime = Math.max(0, Math.min(state.buffer.duration, player.currentTime + (event.key === 'ArrowLeft' ? -5 : 5))); }\n});\n$('fullscreen').addEventListener('click', () => { (document.fullscreenElement ? document.exitFullscreen() : $('performance').requestFullscreen()).catch(fail); });\n\nfunction download(blob, name) {\n  const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = name;\n  document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 60_000);\n}\nasync function mediaData() {\n  if (state.data) return state.data;\n  const file = state.file;\n  const data = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); });\n  if (state.file === file) state.data = data;\n  return data;\n}\nasync function withBusy(callback) {\n  if (!state.buffer || state.busy || state.draft) return;\n  setBusy(true); rebuildTimeline();\n  try { await callback(); } catch (error) { fail(error); }\n  finally { setBusy(false); rebuildTimeline(); }\n}\n$('html-export').addEventListener('click', () => withBusy(async () => {\n  status('Embedding audio in the original Yue HTML player…');\n  const project = projectSnapshot(), source = await mediaData();\n  const html = buildAudioPlayerHtml({ ...project, source, lyrics: project.lines });\n  download(new Blob([html], { type: 'text/html;charset=utf-8' }), safeFilename(project.title) + '.html');\n  status('HTML player exported with embedded audio and saved timestamps.');\n}));\n$('save-project').addEventListener('click', () => withBusy(async () => {\n  const project = projectSnapshot();\n  const data = { format: 'studio', version: 1, title: project.title, accent: project.accent, lyrics: $('lyrics').value,\n    lyric_timestamps: project.timestamps, media: { name: state.file.name, data: await mediaData() } };\n  download(new Blob([JSON.stringify(data)], { type: 'application/json' }), safeFilename(project.title) + '.studio.json'); status('Project saved, including audio.');\n}));\n$('open-project').addEventListener('click', () => $('project-file').click());\n$('project-file').addEventListener('change', async event => {\n  const file = event.target.files[0]; if (!file || state.busy || state.draft) return;\n  setBusy(true); status('Opening local project…');\n  try {\n    const project = readProject(JSON.parse(await file.text()));\n    const comma = project.media.data.indexOf(','), raw = atob(project.media.data.slice(comma + 1));\n    const bytes = Uint8Array.from(raw, char => char.charCodeAt(0));\n    const media = new File([bytes], project.media.name, { type: project.media.data.slice(5, project.media.data.indexOf(';')) });\n    const buffer = await decodeFile(media);\n    const stamps = validateTimestamps(project.timestamps, project.lines, buffer.duration);\n    adoptMedia(media, buffer, { title: project.title, data: project.media.data });\n    $('accent').value = project.accent; $('lyrics').value = project.lyrics; state.lines = project.lines; state.timestamps = stamps;\n    updateTitle(); rebuildLyrics(); status('Project restored.');\n  } catch (error) { fail(error); } finally { event.target.value = ''; setBusy(false); }\n});\n$('timing-export').addEventListener('click', () => { download(new Blob([JSON.stringify({ lyric_timestamps: state.timestamps }, null, 2)], { type: 'application/json' }), safeFilename($('track-title').value) + '.timing.json'); });\n$('lrc-export').addEventListener('click', () => { download(new Blob([toLrc(state.lines, state.timestamps)], { type: 'text/plain' }), safeFilename($('track-title').value) + '.lrc'); });\n$('timing-import').addEventListener('click', () => $('timing-file').click());\n$('timing-file').addEventListener('change', async event => {\n  try {\n    const file = event.target.files[0]; if (!file || state.busy || state.draft) return;\n    const raw = JSON.parse(await file.text()); state.timestamps = validateTimestamps(Array.isArray(raw) ? raw : raw.lyric_timestamps, state.lines, state.buffer?.duration || Infinity);\n    updateControls(); rebuildTimeline(); syncLyrics(); status('Timestamps imported.');\n  } catch (error) { fail(error); } finally { event.target.value = ''; }\n});\n\n$('video-open').addEventListener('click', () => { $('video-status').textContent = ''; $('video-progress').hidden = true; $('video-dialog').showModal(); });\n$('video-export').addEventListener('click', async () => {\n  if (state.busy) return;\n  state.abort = new AbortController(); const controller = state.abort;\n  setBusy(true); player.pause(); $('video-export').disabled = true; $('video-resolution').disabled = true;\n  $('video-close').disabled = true; $('video-cancel').hidden = false; $('video-progress').hidden = false; $('video-progress').value = 0;\n  try {\n    const [width, height] = $('video-resolution').value.split(',').map(Number);\n    $('video-status').textContent = 'Preparing encoders…';\n    const blob = await exportMp4(state.buffer, projectSnapshot(), { width, height, signal: controller.signal, onProgress: fraction => {\n      $('video-progress').value = fraction; $('video-status').textContent = `Encoding ${Math.round(fraction * 100)}%`;\n    } });\n    download(blob, safeFilename($('track-title').value) + '.mp4');\n    $('video-status').textContent = 'MP4 exported.'; status('MP4 exported with audio and lyric timing.');\n  } catch (error) {\n    $('video-status').textContent = error.name === 'AbortError' ? 'Export cancelled.' : error.message;\n    if (error.name !== 'AbortError') fail(error);\n  } finally {\n    state.abort = null; setBusy(false); $('video-export').disabled = false; $('video-resolution').disabled = false;\n    $('video-close').disabled = false; $('video-cancel').hidden = true;\n  }\n});\n$('video-cancel').addEventListener('click', () => state.abort?.abort());\n$('video-dialog').addEventListener('cancel', event => { if (state.abort) { event.preventDefault(); state.abort.abort(); } });\n$('about-open').addEventListener('click', () => $('about-dialog').showModal());\n$('source-download').addEventListener('click', () => {\n  const bundle = JSON.parse($('studio-source').textContent);\n  download(new Blob([JSON.stringify(bundle, null, 2)], { type: 'application/json' }), 'studio-source.json');\n});\nwindow.addEventListener('beforeunload', event => {\n  if (state.file) { event.preventDefault(); event.returnValue = ''; }\n});\nwindow.addEventListener('pagehide', () => { state.abort?.abort(); if (state.url) URL.revokeObjectURL(state.url); });\nupdateControls(); updateTitle(); paint();\n","src/index.html":"\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n  \u003cmeta charset=\"utf-8\">\n  \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  \u003cmeta name=\"color-scheme\" content=\"dark\">\n  \u003cmeta http-equiv=\"Content-Security-Policy\" content=\"connect-src 'none'; object-src 'none'; base-uri 'none'\">\n  \u003cmeta name=\"description\" content=\"Local audio and lyric timing studio.\">\n  \u003ctitle>studio\u003c/title>\n  \u003cstyle>/* STUDIO_CSS */\u003c/style>\n\u003c/head>\n\u003cbody>\n  \u003cheader class=\"topbar\">\n    \u003ca class=\"wordmark\" href=\"#\" aria-label=\"studio home\">\u003cspan class=\"mark\">▥\u003c/span> studio\u003cspan class=\"version\">/ 01\u003c/span>\u003c/a>\n    \u003cnav aria-label=\"Project\">\n      \u003cbutton id=\"open-project\">Open project\u003c/button>\u003cbutton id=\"save-project\" disabled>Save project\u003c/button>\n      \u003cbutton id=\"html-export\" class=\"primary\" disabled>Export HTML \u003cspan>↗\u003c/span>\u003c/button>\n      \u003cbutton id=\"video-open\" disabled>Export MP4 \u003cspan>↗\u003c/span>\u003c/button>\n    \u003c/nav>\n  \u003c/header>\n  \u003cmain>\n    \u003cdiv class=\"workspace-heading\">\u003cspan>\u003ci>\u003c/i> LOCAL WORKSPACE\u003c/span>\u003cspan id=\"session-info\">No media loaded\u003c/span>\u003c/div>\n    \u003cdiv class=\"workbench\">\n      \u003caside class=\"editor\">\n        \u003csection class=\"panel\">\n          \u003cdiv class=\"section-heading\">\u003ch1>\u003cspan>01\u003c/span> Source\u003c/h1>\u003cspan id=\"media-size\">—\u003c/span>\u003c/div>\n          \u003clabel class=\"dropzone\" id=\"media-drop\" for=\"media-file\">\u003cspan class=\"upload-icon\">↑\u003c/span>\u003cstrong id=\"media-name\">Drop audio or choose a file\u003c/strong>\u003csmall>FLAC · M4A · MP3 · WAV · video audio\u003c/small>\u003c/label>\n          \u003cinput type=\"file\" id=\"media-file\" accept=\"audio/*,video/*,.flac,.m4a,.mp3,.wav,.aiff,.aif,.ogg,.opus,.aac\" class=\"file-input\">\n          \u003cdiv class=\"title-row\">\u003clabel>Title\u003cinput id=\"track-title\" placeholder=\"Untitled\" maxlength=\"2000\">\u003c/label>\u003clabel class=\"accent-label\">Accent\u003cinput type=\"color\" id=\"accent\" value=\"#90efb8\">\u003c/label>\u003c/div>\n        \u003c/section>\n        \u003csection class=\"panel lyrics-editor\">\n          \u003cdiv class=\"section-heading\">\u003ch2>\u003cspan>02\u003c/span> Lyrics\u003c/h2>\u003cbutton id=\"lyrics-open\" class=\"text-button\">Import .md ↗\u003c/button>\u003c/div>\n          \u003clabel class=\"sr-only\" for=\"lyrics\">Lyrics\u003c/label>\n          \u003ctextarea id=\"lyrics\" placeholder=\"[Verse 1]&#10;One line at a time&#10;As the words arrive\" spellcheck=\"false\">\u003c/textarea>\n          \u003cdiv class=\"editor-footer\">\u003cspan id=\"line-count\">0 lines\u003c/span>\u003cspan>Blank lines are ignored\u003c/span>\u003c/div>\n          \u003cinput type=\"file\" id=\"lyrics-file\" accept=\".md,.txt,.lrc,text/plain,text/markdown\" class=\"file-input\">\n        \u003c/section>\n        \u003cdetails class=\"panel timings-panel\" id=\"timings-panel\">\n          \u003csummary>\u003cspan>03\u003c/span> Timeline \u003cspan id=\"stamp-count\">0 timed\u003c/span>\u003c/summary>\n          \u003cdiv class=\"timeline-tools\">\u003cbutton id=\"timing-import\">Import JSON\u003c/button>\u003cbutton id=\"timing-export\" disabled>Export JSON\u003c/button>\u003cbutton id=\"lrc-export\" disabled>LRC\u003c/button>\u003c/div>\n          \u003cdiv id=\"timeline\" class=\"timeline\">\u003cp class=\"muted\">Mark lyrics to build a timeline.\u003c/p>\u003c/div>\n          \u003cbutton id=\"clear-timings\" class=\"text-button\" disabled>Clear timestamps\u003c/button>\n          \u003cinput type=\"file\" id=\"timing-file\" accept=\".json,application/json\" class=\"file-input\">\n        \u003c/details>\n      \u003c/aside>\n      \u003csection class=\"preview-area\">\n        \u003cdiv class=\"preview-toolbar\">\u003cspan>PERFORMANCE\u003c/span>\u003cbutton id=\"fullscreen\" class=\"text-button\">Fullscreen ⛶\u003c/button>\u003c/div>\n        \u003cdiv class=\"performance\" id=\"performance\">\n          \u003cdiv class=\"performance-top\">\u003cspan id=\"mode-label\">PREVIEW\u003c/span>\u003cspan id=\"performance-clock\">00:00 / 00:00\u003c/span>\u003c/div>\n          \u003cdiv class=\"performance-body\">\u003cdiv class=\"track-meta\">\u003cspan class=\"meta-label\">TITLE\u003c/span>\u003ch2 id=\"preview-title\">Untitled\u003c/h2>\u003cspan class=\"meta-label\">SOURCE\u003c/span>\u003cp id=\"preview-source\">—\u003c/p>\u003cspan class=\"meta-label\">TIMING\u003c/span>\u003cp id=\"preview-timing\">Manual / not started\u003c/p>\u003c/div>\n            \u003cdiv id=\"lyric-preview\" class=\"lyric-preview\">\u003cdiv class=\"empty-state\">\u003cspan>∷\u003c/span>\u003cp>Your lyrics appear here.\u003c/p>\u003csmall>Load audio, add words, then mark each line.\u003c/small>\u003c/div>\u003c/div>\n          \u003c/div>\n          \u003ccanvas id=\"spectrum\" aria-label=\"Audio spectrum\">\u003c/canvas>\n          \u003cdiv class=\"player-wrap\">\u003caudio id=\"player\" controls preload=\"metadata\">\u003c/audio>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sync-panel\">\n          \u003cdiv class=\"sync-header\">\u003cdiv>\u003cspan class=\"eyebrow\">MANUAL SYNC\u003c/span>\u003cp id=\"sync-instruction\">Mark the moment each lyric begins.\u003c/p>\u003c/div>\u003cbutton id=\"sync-start\" disabled>Start timing\u003c/button>\u003c/div>\n          \u003cdiv id=\"sync-controls\" class=\"sync-controls\" hidden>\u003cbutton id=\"stamp\" class=\"stamp-button\">Mark line \u003ckbd>Enter\u003c/kbd>\u003c/button>\u003cbutton id=\"undo\" disabled>Undo\u003c/button>\u003cbutton id=\"sync-save\" class=\"primary\">Save timing\u003c/button>\u003cbutton id=\"sync-cancel\">Cancel\u003c/button>\u003c/div>\n          \u003cdiv class=\"shortcuts\">\u003cspan>\u003ckbd>Space\u003c/kbd> Play / pause\u003c/span>\u003cspan>\u003ckbd>←\u003c/kbd>\u003ckbd>→\u003c/kbd> Seek 5s\u003c/span>\u003cspan>Click a lyric to select or seek\u003c/span>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"status\" role=\"status\" aria-live=\"polite\">\u003ci id=\"status-dot\">\u003c/i>\u003cspan id=\"status-text\">Ready. Files stay in this browser.\u003c/span>\u003c/div>\n      \u003c/section>\n    \u003c/div>\n  \u003c/main>\n  \u003cfooter class=\"page-footer\">\u003cspan>studio \u003cspan class=\"subtle\">/ local audio + lyric timing\u003c/span>\u003c/span>\u003cbutton id=\"about-open\" class=\"text-button\">Source & licenses\u003c/button>\u003c/footer>\n  \u003cinput type=\"file\" id=\"project-file\" accept=\".studio.json,.json,application/json\" class=\"file-input\">\n  \u003cdialog id=\"video-dialog\">\n    \u003cform method=\"dialog\" class=\"dialog-header\">\u003ch2>Export MP4\u003c/h2>\u003cbutton aria-label=\"Close\" id=\"video-close\">×\u003c/button>\u003c/form>\n    \u003cp class=\"muted\">Performance view · H.264 video + AAC audio · 30 fps\u003c/p>\n    \u003clabel>Resolution\u003cselect id=\"video-resolution\">\u003coption value=\"1280,720\">1280 × 720 · landscape\u003c/option>\u003coption value=\"1920,1080\">1920 × 1080 · landscape\u003c/option>\u003coption value=\"1080,1920\">1080 × 1920 · portrait\u003c/option>\u003c/select>\u003c/label>\n    \u003cp class=\"small muted\">Encoded locally, without playing or recording your screen. Large exports need sufficient browser memory. Native stem separation is not included.\u003c/p>\n    \u003cprogress id=\"video-progress\" value=\"0\" max=\"1\" hidden>\u003c/progress>\u003cp id=\"video-status\" role=\"status\">\u003c/p>\n    \u003cdiv class=\"dialog-actions\">\u003cbutton id=\"video-cancel\" hidden>Cancel export\u003c/button>\u003cbutton id=\"video-export\" class=\"primary\">Export MP4\u003c/button>\u003c/div>\n  \u003c/dialog>\n  \u003cdialog id=\"about-dialog\">\u003cform method=\"dialog\" class=\"dialog-header\">\u003ch2>studio\u003c/h2>\u003cbutton aria-label=\"Close\">×\u003c/button>\u003c/form>\n    \u003cp>Standalone lyric studio derived from mm-tools Yue2. The HTML player builder is unmodified. Stem separation in the original requires Python models and is not included here.\u003c/p>\n    \u003cp>All processing is local. No uploads, analytics, external fonts, or runtime downloads.\u003c/p>\n    \u003cbutton id=\"source-download\">Download corresponding source\u003c/button>\n    \u003cdetails>\u003csummary>Licenses and provenance\u003c/summary>\u003cpre id=\"licenses\">STUDIO_LICENSES\u003c/pre>\u003c/details>\n  \u003c/dialog>\n  \u003cscript id=\"studio-source\" type=\"application/json\">STUDIO_SOURCE\u003c/script>\n  \u003cscript>/* STUDIO_JS */\u003c/script>\n\u003c/body>\n\u003c/html>\n","src/style.css":":root{--bg:#0d1010;--panel:#131817;--line:#29312d;--text:#e5ede8;--muted:#8d9b93;--accent:#90efb8;--red:#e99991;color-scheme:dark;font:13px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,input,textarea,select{font:inherit}button,a,input,textarea,select{-webkit-tap-highlight-color:transparent}button{padding:9px 13px;border:1px solid #354039;border-radius:5px;background:#1a211d;color:var(--text);cursor:pointer;white-space:nowrap}button:hover:not(:disabled){border-color:#6b8576;background:#222c26}button:disabled{opacity:.35;cursor:not-allowed}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.primary{background:var(--accent);color:#0d2015;border-color:var(--accent)}.primary:hover:not(:disabled){background:#b2f7cf;color:#0d2015}.text-button{border:0;background:transparent;padding:3px 0;color:var(--muted);font-size:11px}.text-button:hover:not(:disabled){background:transparent;color:var(--text)}[hidden]{display:none!important}a{color:inherit}.topbar{padding:21px 3.8%;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line)}.wordmark{display:flex;align-items:center;gap:10px;font:600 24px/1.2 system-ui,sans-serif;letter-spacing:-.8px;text-decoration:none}.mark{color:var(--accent);font:26px monospace}.version{align-self:flex-end;margin:0 0 2px 8px;color:#69776f;font:10px monospace;letter-spacing:0}nav{display:flex;gap:8px}nav button{font-size:11px}nav button span{margin-left:9px}main{max-width:1600px;padding:24px 3.8% 35px;margin:auto}.workspace-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:18px;color:var(--muted);font-size:10px;letter-spacing:1.5px}.workspace-heading i,.status i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent);margin-right:9px}.workbench{display:grid;grid-template-columns:minmax(270px,345px) minmax(0,1fr);gap:24px}.editor{display:flex;flex-direction:column;gap:15px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:19px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:17px}.section-heading h1,.section-heading h2{font:500 12px monospace;margin:0}.section-heading h1 span,.section-heading h2 span,summary>span:first-child{color:#65776b;margin-right:9px;font-size:10px}.section-heading>span{font-size:10px;color:var(--muted)}.dropzone{border:1px dashed #3a4e40;border-radius:5px;min-height:144px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:18px 8px;cursor:pointer;gap:8px;transition:background .15s}.dropzone:hover,.dropzone.dragging{background:#1d2b22;border-color:var(--accent)}.dropzone strong{font-size:11px;font-weight:400;word-break:break-all}.dropzone small{font-size:9px;color:#819187}.upload-icon{font-size:23px;color:var(--accent);line-height:1;margin-bottom:4px}.file-input{display:none}.title-row{display:flex;gap:12px;margin-top:18px}.title-row label:first-child{flex:1;min-width:0}label{display:block;color:var(--muted);font-size:10px}input,textarea,select{width:100%;display:block;margin-top:7px;background:#0e1310;color:var(--text);border:1px solid #303e34;border-radius:4px;padding:9px}input:focus,textarea:focus,select:focus{outline:1px solid var(--accent);border-color:var(--accent)}input[type=color]{height:36px;width:43px;padding:4px;cursor:pointer}.lyrics-editor textarea{resize:vertical;min-height:232px;border:0;padding:0;background:transparent;line-height:1.9;font-size:12px}.lyrics-editor textarea:focus{outline:0}.lyrics-editor:focus-within{border-color:#698975}.editor-footer{display:flex;justify-content:space-between;gap:5px;color:#728377;font-size:9px;margin-top:12px;padding-top:14px;border-top:1px solid var(--line)}summary{cursor:pointer;font-size:12px;list-style-position:outside}summary::marker{color:#718579}summary #stamp-count{float:right;margin:2px 0 0;color:var(--muted);font-size:10px}.timings-panel[open] summary{margin-bottom:16px}.timeline-tools{display:flex;gap:6px}.timeline-tools button{font-size:9px;padding:6px 8px}.timeline{max-height:230px;overflow:auto;margin:14px 0}.timeline-row{display:flex;align-items:center;gap:8px;border-bottom:1px solid var(--line);padding:7px 0}.timeline-row span{flex:1;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.timeline-row input{width:78px;font-size:10px;margin:0;padding:5px}.timeline-row button{border:0;padding:4px;background:none}.preview-toolbar{display:flex;justify-content:space-between;align-items:center;margin:0 1px 13px;font-size:10px;color:var(--muted);letter-spacing:1.5px}.performance{background:#050706;border:1px solid var(--line);border-radius:7px;padding:23px 26px 15px;position:relative;min-height:421px;display:flex;flex-direction:column}.performance-top{display:flex;justify-content:space-between;gap:10px;font-size:9px;color:#74837a;letter-spacing:1px}.performance-top #mode-label{color:var(--accent)}.performance-body{display:grid;grid-template-columns:minmax(130px,34%) minmax(0,1fr);gap:30px;margin:31px 0 24px;min-height:214px;flex:1}.meta-label{display:block;font-size:8px;color:#64776a;letter-spacing:1.7px;margin-bottom:8px}.track-meta h2{font:500 21px/1.35 system-ui,sans-serif;overflow-wrap:anywhere;margin:0 0 25px}.track-meta p{font-size:10px;color:#9aa99f;overflow-wrap:anywhere;margin:0 0 23px}.lyric-preview{position:relative;overflow:auto;max-height:300px;scrollbar-width:thin;scrollbar-color:#304237 transparent;padding:0 10px 26px 0}.lyric-row{display:flex;align-items:baseline;gap:14px;width:100%;border:0;background:none;border-radius:0;text-align:left;white-space:normal;padding:6px 0;font:14px/1.65 system-ui,sans-serif;color:#87938b}.lyric-row:hover:not(:disabled){background:none;border:0;color:#e5ede8}.lyric-row small{width:15px;flex-shrink:0;font:8px monospace;color:#43574a}.lyric-row.active{color:var(--accent)}.lyric-row.section{font:9px/1.8 monospace;color:#657b6b;letter-spacing:1.2px;margin-top:10px;cursor:default}.lyric-row.pending{color:var(--red)}.lyric-row.recorded small{color:var(--accent)}.empty-state{padding:18px 0;color:#86988c}.empty-state>span{font-size:28px;color:#385641}.empty-state p{font-size:13px;margin:16px 0 7px}.empty-state small{font:10px/1.7 monospace;color:#5f7566}#spectrum{width:100%;height:64px;display:block;opacity:.9}.player-wrap{margin-top:20px}audio{width:100%;height:35px;display:block;filter:contrast(.9)}.sync-panel{margin-top:16px;border:1px solid var(--line);border-radius:6px;padding:20px 22px;background:#141b17}.sync-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{font-size:9px;color:var(--accent);letter-spacing:1.4px}.sync-header p{font-size:11px;margin:5px 0 0;color:var(--muted)}.sync-header button{font-size:11px}.sync-controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:20px}.stamp-button{flex:1;text-align:left;background:#222e25;border-color:#55795f;min-width:150px}.stamp-button kbd{float:right}.shortcuts{display:flex;flex-wrap:wrap;gap:12px;margin-top:19px;border-top:1px solid #28382d;padding-top:13px;font-size:9px;color:#788c7e}kbd{padding:1px 4px;border:1px solid #394f40;border-radius:3px;font:9px monospace;color:#a4bdac}.status{display:flex;align-items:center;margin:16px 2px;font-size:10px;color:var(--muted);min-height:22px;overflow-wrap:anywhere}.status i{flex-shrink:0;background:#4d6b56}.status.error{color:var(--red)}.status.error i{background:var(--red)}.page-footer{margin:0 3.8%;padding:18px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:#84958a;font-size:10px}.subtle{color:#52695a;margin-left:12px}.muted{color:var(--muted)}.small{font-size:11px}dialog{background:#141c17;color:var(--text);border:1px solid #3a5140;border-radius:9px;padding:25px;width:min(500px,95vw);max-height:88vh}dialog::backdrop{background:#020504cc;backdrop-filter:blur(4px)}.dialog-header{display:flex;align-items:center;justify-content:space-between}.dialog-header h2{font-size:17px;margin:0}.dialog-header button{background:none;border:0;font-size:23px;padding:0 4px;color:var(--muted)}dialog p{line-height:1.8}dialog label{margin:20px 0}dialog select{font-size:12px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}progress{width:100%;accent-color:var(--accent)}#video-status{font-size:11px;min-height:20px}#about-dialog pre{white-space:pre-wrap;font-size:10px;max-height:35vh;overflow:auto}.sr-only{position:absolute;overflow:hidden;clip:rect(0,0,0,0);width:1px;height:1px}.performance:fullscreen{width:100vw;height:100vh;padding:4vh 5vw;border:0;border-radius:0}.performance:fullscreen .performance-body{min-height:0;align-items:center}.performance:fullscreen .lyric-preview{max-height:65vh}.performance:fullscreen .lyric-row{font-size:clamp(18px,2.2vw,36px)}.performance:fullscreen .lyric-row.section{font-size:14px}.performance:fullscreen .track-meta h2{font-size:clamp(25px,3vw,45px)}.performance:fullscreen #spectrum{height:13vh}\n@media(min-width:1400px){.performance{min-height:500px}.performance-body{margin-top:45px}.lyric-preview{max-height:360px}.lyrics-editor textarea{min-height:270px}}\n@media(max-width:900px){.topbar{align-items:flex-start;flex-direction:column;gap:18px}.topbar nav{width:100%;flex-wrap:wrap}.workbench{grid-template-columns:280px minmax(0,1fr);gap:16px}.panel{padding:15px}.performance{padding:18px}.performance-body{grid-template-columns:1fr;gap:12px;margin-top:20px}.track-meta .meta-label:not(:first-child),.track-meta p{display:none}.track-meta h2{margin-bottom:4px}.lyric-preview{max-height:255px}.sync-panel{padding:15px}.sync-header{align-items:flex-start}.shortcuts span:last-child{display:none}}\n@media(max-width:650px){main{padding-top:18px}.workbench{display:flex;flex-direction:column}.editor{display:grid;grid-template-columns:1fr;gap:12px}.lyrics-editor textarea{min-height:160px}.performance{min-height:390px}.performance-body{grid-template-columns:30% minmax(0,1fr);gap:20px;min-height:170px}.track-meta h2{font-size:17px}.track-meta .meta-label:not(:first-child),.track-meta p{display:block}.lyric-row{font-size:13px}.workspace-heading{font-size:8px;letter-spacing:.6px}.page-footer .subtle{display:none}nav button{font-size:10px;padding:8px 9px}.status{font-size:9px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n","src/render.js":"import { activeLine, formatTime, isSection } from './core.js';\n\n// A 256-sample FFT mirrors the original performance view's analyser resolution.\n// Offline frames use decoded samples rather than recording a playing browser tab.\nexport function spectrumAt(buffer, time, previous = new Float32Array(128)) {\n  const n = 256, re = new Float64Array(n), im = new Float64Array(n);\n  const center = Math.floor(time * buffer.sampleRate);\n  const channels = Array.from({ length: buffer.numberOfChannels }, (_, c) => buffer.getChannelData(c));\n  for (let i = 0; i \u003c n; i++) {\n    const frame = center + i - n / 2;\n    const sample = channels.reduce((sum, channel) => sum + (channel[frame] || 0), 0) / channels.length;\n    re[i] = sample * (0.5 - 0.5 * Math.cos(2 * Math.PI * i / (n - 1)));\n  }\n  for (let i = 1, j = 0; i \u003c n; i++) {\n    let bit = n >> 1;\n    for (; j & bit; bit >>= 1) j ^= bit;\n    j ^= bit;\n    if (i \u003c j) [re[i], re[j]] = [re[j], re[i]];\n  }\n  for (let size = 2; size \u003c= n; size \u003c\u003c= 1) {\n    for (let start = 0; start \u003c n; start += size) {\n      for (let j = 0; j \u003c size / 2; j++) {\n        const angle = -2 * Math.PI * j / size, cosine = Math.cos(angle), sine = Math.sin(angle);\n        const even = start + j, odd = even + size / 2;\n        const r = re[odd] * cosine - im[odd] * sine, imaginary = re[odd] * sine + im[odd] * cosine;\n        re[odd] = re[even] - r; im[odd] = im[even] - imaginary;\n        re[even] += r; im[even] += imaginary;\n      }\n    }\n  }\n  for (let i = 0; i \u003c n / 2; i++) {\n    const magnitude = Math.hypot(re[i], im[i]) / (n / 4);\n    const level = Math.max(0, Math.min(1, (20 * Math.log10(Math.max(magnitude, 1e-6)) + 80) / 80));\n    previous[i] = previous[i] * 0.82 + level * 0.18;\n  }\n  return previous;\n}\n\nexport function drawBars(ctx, bins, width, height, color = '#e9eeeb') {\n  const count = 72, gap = width * 0.003, bar = Math.max(1, (width - (count - 1) * gap) / count);\n  ctx.fillStyle = color;\n  for (let i = 0; i \u003c count; i++) {\n    const amplitude = bins[Math.floor(i / count * bins.length)] || 0;\n    const level = Math.max(2, amplitude * height);\n    ctx.fillRect(i * (bar + gap), height - level, bar, level);\n  }\n}\n\nfunction wrap(ctx, text, width) {\n  const rows = [], words = text.split(/\\s+/);\n  let row = '';\n  for (const word of words) {\n    if (row && ctx.measureText(row + ' ' + word).width > width) { rows.push(row); row = ''; }\n    // Handle long unbroken text too; don't paint outside the lyric column.\n    for (const char of (row ? ' ' : '') + word) {\n      if (row && ctx.measureText(row + char).width > width) { rows.push(row); row = ''; }\n      row += char;\n    }\n  }\n  if (row) rows.push(row);\n  return rows;\n}\n\nexport function drawPerformance(canvas, project, time, duration, bins) {\n  const ctx = canvas.getContext('2d'), w = canvas.width, h = canvas.height;\n  const unit = Math.min(w / 1280, h / 720), pad = 52 * unit;\n  ctx.fillStyle = '#050706'; ctx.fillRect(0, 0, w, h);\n  const portrait = w \u003c h, column = portrait ? pad : w * 0.42, top = portrait ? h * 0.24 : pad;\n  const lyricWidth = w - column - pad;\n  ctx.font = `${12 * unit}px monospace`; ctx.fillStyle = '#718079';\n  ctx.fillText('STUDIO / PERFORMANCE', pad, pad);\n  ctx.font = `600 ${26 * unit}px sans-serif`; ctx.fillStyle = '#e9eeeb';\n  const titleRows = wrap(ctx, project.title || 'Untitled', portrait ? w - 2 * pad : column - 2 * pad);\n  titleRows.slice(0, 3).forEach((row, i) => ctx.fillText(row, pad, pad + (48 + i * 34) * unit));\n  ctx.font = `${13 * unit}px monospace`; ctx.fillStyle = project.accent;\n  ctx.fillText(formatTime(time) + ' / ' + formatTime(duration), pad, pad + (70 + Math.min(3, titleRows.length) * 34) * unit);\n  const selected = activeLine(project.lines, project.timestamps, time, duration);\n  const rowHeight = 35 * unit, viewport = h - top - 160 * unit;\n  const laidOut = project.lines.map((text, index) => {\n    ctx.font = `${(isSection(text) ? 13 : 20) * unit}px sans-serif`;\n    return { index, section: isSection(text), rows: wrap(ctx, text, lyricWidth) };\n  });\n  let selectedY = 0, total = 0;\n  laidOut.forEach(item => { if (item.index === selected) selectedY = total; total += item.rows.length * rowHeight + 12 * unit; });\n  let y = top - Math.max(0, Math.min(selectedY - viewport * 0.38, total - viewport));\n  ctx.save(); ctx.beginPath(); ctx.rect(column, top - rowHeight, lyricWidth, viewport + rowHeight); ctx.clip();\n  for (const item of laidOut) {\n    ctx.fillStyle = item.section ? '#64756a' : item.index === selected ? project.accent : '#87928c';\n    ctx.font = `${item.index === selected ? '600 ' : ''}${(item.section ? 13 : 20) * unit}px ${item.section ? 'monospace' : 'sans-serif'}`;\n    for (const row of item.rows) { ctx.fillText(row, column, y + rowHeight); y += rowHeight; }\n    y += 12 * unit;\n  }\n  ctx.restore();\n  ctx.save(); ctx.translate(pad, h - 115 * unit);\n  drawBars(ctx, bins, w - pad * 2, 75 * unit); ctx.restore();\n}\n","src/video.js":"import { Output, Mp4OutputFormat, BufferTarget, CanvasSource, AudioBufferSource, canEncodeAudio, canEncodeVideo, Quality } from 'mediabunny';\nimport { registerAacEncoder } from '@mediabunny/aac-encoder';\nimport { drawPerformance, spectrumAt } from './render.js';\n\nlet fallbackRegistered = false;\nexport async function exportMp4(buffer, project, { width = 1280, height = 720, signal, onProgress = () => {} } = {}) {\n  if (!globalThis.VideoEncoder || !globalThis.isSecureContext) {\n    throw Error('MP4 export needs WebCodecs in a secure browser context. Use localhost or HTTPS in a current Chromium browser. HTML export works independently.');\n  }\n  const frameRate = 30, quality = new Quality({ bitrate: width * height > 1_000_000 ? 5_000_000 : 2_500_000 });\n  if (!(await canEncodeVideo('avc', { width, height, frameRate, quality }))) {\n    throw Error('This browser has no H.264 encoder for the selected resolution. Try 720p in a current Chromium browser.');\n  }\n  if (!fallbackRegistered && !(await canEncodeAudio('aac', { numberOfChannels: buffer.numberOfChannels, sampleRate: buffer.sampleRate }))) {\n    registerAacEncoder(); fallbackRegistered = true;\n  }\n  signal?.throwIfAborted();\n  const canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height;\n  const target = new BufferTarget();\n  const output = new Output({ format: new Mp4OutputFormat({ fastStart: 'in-memory' }), target });\n  const video = new CanvasSource(canvas, { codec: 'avc', quality });\n  const audio = new AudioBufferSource({ codec: 'aac', quality: new Quality({ bitrate: 192_000 }) });\n  output.addVideoTrack(video, { frameRate }); output.addAudioTrack(audio);\n  const abort = () => { output.cancel().catch(() => {}); };\n  signal?.addEventListener('abort', abort, { once: true });\n  try {\n    await output.start();\n    const bins = new Float32Array(128), frames = Math.ceil(buffer.duration * frameRate);\n    await Promise.all([\n      (async () => { await audio.add(buffer); audio.close(); })(),\n      (async () => {\n        for (let frame = 0; frame \u003c frames; frame++) {\n          signal?.throwIfAborted();\n          const time = frame / frameRate;\n          drawPerformance(canvas, project, time, buffer.duration, spectrumAt(buffer, time, bins));\n          await video.add(time, Math.min(1 / frameRate, buffer.duration - time));\n          if (frame % 6 === 0) { onProgress(frame / frames); await new Promise(resolve => setTimeout(resolve, 0)); }\n        }\n        video.close();\n      })(),\n    ]);\n    signal?.throwIfAborted();\n    await output.finalize(); onProgress(1);\n    return new Blob([target.buffer], { type: 'video/mp4' });\n  } catch (error) {\n    await output.cancel().catch(() => {});\n    if (signal?.aborted) throw new DOMException('Export cancelled.', 'AbortError');\n    throw error;\n  } finally { signal?.removeEventListener('abort', abort); }\n}\n","scripts/vendor-yue.ts":"// Mechanical, pinned extraction. The player builder is deliberately unchanged.\nimport { mkdir, readFile, writeFile, copyFile } from 'node:fs/promises'\nimport { resolve, join } from 'node:path'\nimport { createHash } from 'node:crypto'\n\nconst revision = '789efc7778e4c05a948bffb3c96ea91c03844c44'\nconst checkout = resolve(process.argv[2] ?? '../../scratch/mm-tools-studio-reference')\nconst actualRevision = Bun.spawnSync(['git', '-C', checkout, 'rev-parse', 'HEAD']);\nif (actualRevision.exitCode || actualRevision.stdout.toString().trim() !== revision) {\n  throw Error('Checkout must be at the pinned revision ' + revision + '. Review updates before changing the pin.');\n}\nconst root = resolve(import.meta.dir, '..')\nconst file = 'music/yue2/local_app/web/app.js'\nconst app = await readFile(join(checkout, file), 'utf8')\nconst ranges = [\n  ['escapeHtml', 'function escapeHtml(', '\\nfunction formatBytes('],\n  ['hexToRgb', 'function hexToRgb(', '\\nfunction setPage('],\n  ['buildAudioPlayerHtml', 'function buildAudioPlayerHtml(', '\\nfunction exportAudioPlayer('],\n  ['audioBufferToWav', 'function audioBufferToWav(', '\\nfunction authHeaders('],\n]\nconst functions = ranges.map(([name, start, end]) => {\n  const from = app.indexOf(start!), to = app.indexOf(end!, from)\n  if (from \u003c 0 || to \u003c 0) throw Error('Missing original function: ' + name)\n  return { name, source: app.slice(from, to).trimEnd() }\n})\nawait mkdir(join(root, 'src/vendor'), { recursive: true })\nawait writeFile(join(root, 'src/vendor/yue-player.js'),\n  `// Unmodified functions from CommanderTurtle/mm-tools @ ${revision}\\n// ${file} — AGPL-3.0-only; see LICENSE and THIRD_PARTY_NOTICES.md.\\n\\n`\n  + functions.map(f => f.source).join('\\n\\n')\n  + '\\n\\nexport { ' + functions.map(f => f.name).join(', ') + ' };\\n')\nawait writeFile(join(root, 'src/vendor/upstream.json'), JSON.stringify({\n  repository: 'https://github.com/CommanderTurtle/mm-tools', revision, file,\n  functions: functions.map(f => ({ name: f.name, sha256: createHash('sha256').update(f.source).digest('hex') })),\n}, null, 2) + '\\n')\nawait copyFile(join(checkout, 'LICENSE'), join(root, 'LICENSE'))\nconsole.log('Vendored the original Yue player builder and WAV encoder at ' + revision)\n","scripts/build.ts":"import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';\nimport { resolve, join } from 'node:path';\n\nconst root = resolve(import.meta.dir, '..');\nconst result = await Bun.build({ entrypoints: [join(root, 'src/app.js')], target: 'browser', format: 'iife', minify: true, sourcemap: 'none' });\nif (!result.success) throw new AggregateError(result.logs, 'Build failed');\nif (result.outputs.length !== 1) throw Error('Expected one self-contained JavaScript bundle.');\nconst js = await result.outputs[0].text();\nconst escape = (text: string) => text.replaceAll('&', '&amp;').replaceAll('\u003c', '&lt;').replaceAll('>', '&gt;');\nconst files: Record\u003cstring, string> = {};\nasync function include(path: string) {\n  for (const entry of await readdir(join(root, path), { withFileTypes: true })) {\n    const relative = path + '/' + entry.name;\n    if (entry.isDirectory()) await include(relative); else files[relative] = await readFile(join(root, relative), 'utf8');\n  }\n}\nawait include('src'); await include('scripts'); await include('tests');\nfor (const file of ['package.json', 'bun.lock', '.gitignore', '.gitattributes']) files[file] = await readFile(join(root, file), 'utf8');\nconst license = await readFile(join(root, 'LICENSE'), 'utf8');\n// Escaping script terminators is required even inside JavaScript string literals.\nconst inserts: Record\u003cstring, string> = {\n  '/* STUDIO_CSS */': await readFile(join(root, 'src/style.css'), 'utf8'),\n  STUDIO_SOURCE: JSON.stringify({ format: 'studio-source', version: 1, files }).replaceAll('\u003c', '\\\\u003c'),\n  '/* STUDIO_JS */': js.replace(/\u003c\\/script/gi, '\u003c\\\\/script'),\n};\n// One pass: do not accidentally replace a placeholder inside embedded source.\nconst html = (await readFile(join(root, 'src/index.html'), 'utf8'))\n  .replace(/\\/\\* STUDIO_CSS \\*\\/|STUDIO_SOURCE|\\/\\* STUDIO_JS \\*\\//g, marker => inserts[marker]!);\nawait mkdir(join(root, 'dist'), { recursive: true });\nawait writeFile(join(root, 'dist/index.html'), html);\nconsole.log(`Built dist/index.html (${(Buffer.byteLength(html) / 1024 / 1024).toFixed(2)} MB); JS, AAC WASM, license and source embedded.`);\n","scripts/check-browser.ts":"// Optional real-browser AAC/WASM integration harness. No production hooks.\nimport { mkdir, writeFile } from 'node:fs/promises';\nimport { resolve } from 'node:path';\nconst root = resolve(import.meta.dir, '..');\nconst result = await Bun.build({ entrypoints: [root + '/tests/encoder-harness.js'], target: 'browser', format: 'iife', minify: true });\nif (!result.success) throw Error('Harness build failed');\nconst js = (await result.outputs[0].text()).replace(/\u003c\\/script/gi, '\u003c\\\\/script');\nconst html = `\u003c!doctype html>\u003cmeta charset=\"utf-8\">\u003cmeta http-equiv=\"Content-Security-Policy\" content=\"connect-src 'none'; object-src 'none'; base-uri 'none'\">\u003ctitle>studio encoder check\u003c/title>\u003cbody style=\"background:#111;color:#eee;font:16px monospace;padding:30px\">\u003ch1>Encoder integration check\u003c/h1>\u003clabel>Audio fixture\u003cinput type=\"file\" id=\"file\">\u003c/label>\u003cbutton id=\"encode\">Encode software AAC\u003c/button>\u003cbutton id=\"cancel\">Cancel\u003c/button>\u003cp id=\"state\">Choose a fixture\u003c/p>\u003cscript>${js}\u003c/script>`;\nawait mkdir(root + '/.work', { recursive: true }); await writeFile(root + '/.work/encoder-check.html', html);\nconst server = Bun.serve({ hostname: '127.0.0.1', port: 8195, fetch: () => new Response(html, { headers: { 'Content-Type': 'text/html' } }) });\nconsole.log('Encoder harness: http://' + server.hostname + ':' + server.port);\n","scripts/check-player.ts":"import { readFile } from 'node:fs/promises';\nimport { parseLyrics } from '../src/core.js';\nimport { buildAudioPlayerHtml } from '../src/vendor/yue-player.js';\nconst path = process.argv[2];\nif (!path) throw Error('Pass the HTML export of studio-check.wav with the generated lyrics/timing fixtures.');\nconst html = await readFile(path, 'utf8');\nconst source = html.match(/\u003caudio id=\"player\" src=\"([^\"]+)\"/)?.[1];\nif (!source?.startsWith('data:audio/')) throw Error('Export has no embedded audio.');\nconst lyrics = parseLyrics(await readFile(new URL('../.work/fixtures/lyrics.md', import.meta.url), 'utf8'));\nconst { lyric_timestamps: timestamps } = JSON.parse(await readFile(new URL('../.work/fixtures/timing.json', import.meta.url), 'utf8'));\nconst expected = buildAudioPlayerHtml({ title: 'studio-check', source, accent: '#90efb8', lyrics, timestamps });\nif (html !== expected) throw Error('Downloaded player differs from original Yue builder output.');\nconsole.log('Exact Yue output parity; media embedded; ' + timestamps.length + ' saved timestamps.');\n","scripts/restore-source.ts":"// Reconstruct the source bundle downloaded from the standalone page.\n// Refuse existing destinations and traversal rather than overwrite user files.\nimport { readFile, mkdir, writeFile, access } from 'node:fs/promises';\nimport { resolve, join, relative, isAbsolute } from 'node:path';\nconst [bundlePath, destination] = process.argv.slice(2);\nif (!bundlePath || !destination) throw Error('Usage: bun scripts/restore-source.ts studio-source.json NEW_DIRECTORY');\nconst root = resolve(destination);\ntry { await access(root); throw Error('Destination already exists. Choose a new directory.'); }\ncatch (error) { if (error.code !== 'ENOENT') throw error; }\nconst bundle = JSON.parse(await readFile(bundlePath, 'utf8'));\nif (bundle.format !== 'studio-source' || bundle.version !== 1 || !bundle.files) throw Error('Invalid source bundle.');\nfor (const [path, contents] of Object.entries(bundle.files)) {\n  const target = resolve(root, path), inside = relative(root, target);\n  if (!inside || inside.startsWith('..') || isAbsolute(inside) || typeof contents !== 'string') throw Error('Invalid source path.');\n}\nawait mkdir(root);\nfor (const [path, contents] of Object.entries(bundle.files)) {\n  const target = join(root, path); await mkdir(resolve(target, '..'), { recursive: true }); await writeFile(target, contents as string);\n}\nconsole.log('Source restored to ' + root);\n","scripts/fixtures.ts":"// Small generated media for browser QA; never included in dist.\nimport { mkdir, writeFile } from 'node:fs/promises';\nimport { join, resolve } from 'node:path';\nimport { audioBufferToWav } from '../src/vendor/yue-player.js';\nconst path = resolve(import.meta.dir, '../.work/fixtures');\nawait mkdir(path, { recursive: true });\nconst rate = 48000, length = rate * 6;\nconst signal = Float32Array.from({ length }, (_, i) => .17 * Math.sin(2 * Math.PI * (i \u003c rate * 3 ? 220 : 440) * i / rate) * Math.min(1, i / 1000, (length - i) / 1000));\nawait writeFile(join(path, 'studio-check.wav'), audioBufferToWav({ numberOfChannels: 1, length, sampleRate: rate, getChannelData: () => signal }));\nawait writeFile(join(path, 'lyrics.md'), '[Verse 1]\\n\\nSignal in the quiet\\n\\n\\nA line across the screen\\n[Chorus]\\nEverything in time\\n');\nawait writeFile(join(path, 'timing.json'), JSON.stringify({ lyric_timestamps: [{ line: 1, start: .5 }, { line: 2, start: 2 }, { line: 4, start: 4 }] }));\nif (process.argv[2]) {\n  for (const [ext, codec] of [['flac', 'flac'], ['mp3', 'libmp3lame'], ['m4a', 'aac']]) {\n    const processResult = Bun.spawnSync([process.argv[2], '-hide_banner', '-loglevel', 'error', '-y', '-i', join(path, 'studio-check.wav'), '-c:a', codec, join(path, 'studio-check.' + ext)]);\n    if (processResult.exitCode) throw Error(processResult.stderr.toString());\n  }\n}\nconsole.log(path);\n","scripts/serve.ts":"import { resolve, join } from 'node:path';\nconst root = resolve(import.meta.dir, '../dist');\nconst port = Number(process.env.PORT || 8194);\nconst server = Bun.serve({ hostname: '127.0.0.1', port, async fetch(request) {\n  const path = new URL(request.url).pathname;\n  if (path === '/favicon.ico') return new Response(null, { status: 204 });\n  if (path !== '/' && path !== '/index.html') return new Response('Not found', { status: 404 });\n  const file = Bun.file(join(root, 'index.html'));\n  if (!await file.exists()) return new Response('Run bun run build first.', { status: 503 });\n  return new Response(file, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });\n} });\nconsole.log(`studio: http://${server.hostname}:${server.port}`);\n","tests/build.test.js":"import { test, expect } from 'bun:test';\nimport { readFileSync, existsSync } from 'node:fs';\nconst url = new URL('../dist/index.html', import.meta.url);\ntest.skipIf(!existsSync(url))('portable build has no external runtime assets and contains reconstructable source', () => {\n  const html = readFileSync(url, 'utf8');\n  expect(html).not.toMatch(/\u003cscript[^>]+src\\s*=/i);\n  expect(html).not.toMatch(/\u003clink[^>]+(?:href|rel)\\s*=/i);\n  expect(html.includes('\u003cscript>/* STUDIO_JS */\u003c/script>')).toBe(false);\n  expect(html.includes('data:application/wasm;base64,')).toBe(true);\n  const source = JSON.parse(html.match(/\u003cscript id=\"studio-source\" type=\"application\\/json\">([\\s\\S]*?)\u003c\\/script>/)[1]);\n  expect(source.files['src/app.js']).toContain('buildAudioPlayerHtml');\n  expect(source.files['bun.lock']).toBeTruthy();\n  expect(source.files['scripts/build.ts']).toBeTruthy();\n});\n","tests/core.test.js":"import { test, expect } from 'bun:test';\nimport { parseLyrics, lyricIndices, activeLine, validateTimestamps, remapTimestamps, readProject, validAccent, toLrc } from '../src/core.js';\nimport { spectrumAt } from '../src/render.js';\n\ntest('plain Markdown ignores extra blank lines and retains section indices', () => {\n  const lines = parseLyrics('\\r\\n[Verse 1]\\r\\n\\r\\n  First line  \\r\\n\\r\\n\\r\\nSecond line\\n');\n  expect(lines).toEqual(['[Verse 1]', 'First line', 'Second line']);\n  expect(lyricIndices(lines)).toEqual([1, 2]);\n});\ntest('timeline selection matches Yue lookahead and untimed fallback', () => {\n  const lines = ['[Verse]', 'One', 'Two'];\n  expect(activeLine(lines, [{ line: 1, start: 1 }, { line: 2, start: 3 }], .8, 4)).toBe(-1);\n  expect(activeLine(lines, [{ line: 1, start: 1 }, { line: 2, start: 3 }], 2.86, 4)).toBe(2);\n  expect(activeLine(lines, [], 0, 4)).toBe(1);\n  expect(activeLine(lines, [], 4, 4)).toBe(2);\n  expect(activeLine([], [], 0, 4)).toBe(-1);\n});\ntest('timestamps are clean numeric row/start records', () => {\n  expect(validateTimestamps([{ line: 1, start: 1.12349, extra: '\u003c/script>' }], ['[Verse]', 'One'], 3))\n    .toEqual([{ line: 1, start: 1.123 }]);\n  for (const raw of [[{ line: 0, start: 0 }], [{ line: 1, start: -1 }], [{ line: 1, start: NaN }], [{ line: 1, start: '1' }], [{ line: 1, start: 9 }], [{ line: 1.5, start: 0 }]]) {\n    expect(() => validateTimestamps(raw, ['[Verse]', 'One'], 3)).toThrow();\n  }\n  expect(() => validateTimestamps([{ line: 0, start: 2 }, { line: 1, start: 1 }], ['One', 'Two'])).toThrow('order');\n  expect(() => validateTimestamps([{ line: 0, start: 1 }, { line: 0, start: 2 }], ['One'])).toThrow('one timestamp');\n});\ntest('text edits remap unchanged repeated lyrics without shifting deleted ones', () => {\n  expect(remapTimestamps(['One', 'Repeat', 'Repeat', 'End'], ['[Verse]', 'One', 'New', 'Repeat', 'Repeat'], [{ line: 0, start: 0 }, { line: 2, start: 2 }, { line: 3, start: 3 }]))\n    .toEqual([{ line: 1, start: 0 }, { line: 4, start: 2 }]);\n  expect(remapTimestamps(['One', 'Two'], ['Two', 'One'], [{ line: 0, start: 0 }, { line: 1, start: 2 }])).toEqual([{ line: 0, start: 2 }]);\n});\ntest('projects accept embedded audio only and sanitize accent/timestamps', () => {\n  const project = { format: 'studio', version: 1, title: 'Title', lyrics: 'One', accent: 'red;bad', media: { data: 'data:audio/wav;base64,AAAA', name: 'song.wav' }, lyric_timestamps: [{ line: 0, start: 0 }] };\n  expect(readProject(project).accent).toBe('#90efb8');\n  expect(() => readProject({ ...project, media: { data: 'https://example.com/audio.mp3' } })).toThrow();\n  expect(() => readProject({ ...project, media: { data: 'data:text/html;base64,AAAA' } })).toThrow();\n  expect(validAccent('#ff00AA')).toBe('#ff00AA');\n});\ntest('LRC export uses minutes and fractional seconds', () => {\n  expect(toLrc(['One', 'Two'], [{ line: 0, start: 1.25 }, { line: 1, start: 62.5 }])).toBe('[00:01.25]One\\n[01:02.50]Two\\n');\n  expect(toLrc(['One'], [{ line: 0, start: 59.999 }])).toBe('[01:00.00]One\\n');\n});\ntest('offline FFT detects a sine instead of inventing an idle spectrum', () => {\n  const data = Float32Array.from({ length: 2048 }, (_, i) => .5 * Math.sin(2 * Math.PI * 8 * i / 256));\n  const buffer = { sampleRate: 48000, numberOfChannels: 1, getChannelData: () => data };\n  const bins = spectrumAt(buffer, .02);\n  expect([...bins].indexOf(Math.max(...bins))).toBe(8);\n  const silence = spectrumAt({ ...buffer, getChannelData: () => new Float32Array(2048) }, .02);\n  expect(Math.max(...silence)).toBe(0);\n});\n","tests/encoder-harness.js":"// Browser integration check only; not an application entrypoint.\nimport { registerAacEncoder } from '@mediabunny/aac-encoder';\nimport { exportMp4 } from '../src/video.js';\nregisterAacEncoder();\nlet buffer, abort;\nconst file = document.getElementById('file'), state = document.getElementById('state');\nfile.addEventListener('change', async () => {\n  buffer = await new AudioContext().decodeAudioData(await file.files[0].arrayBuffer());\n  state.textContent = 'Ready: ' + buffer.duration + ' seconds';\n});\ndocument.getElementById('encode').addEventListener('click', async () => {\n  abort = new AbortController();\n  try {\n    const output = await exportMp4(buffer, { title: 'Software AAC check', accent: '#90efb8', lines: ['[Verse]', 'Software AAC + H.264'], timestamps: [{ line: 1, start: 0 }] }, {\n      width: 640, height: 360, signal: abort.signal, onProgress: value => { state.textContent = 'Encoding: ' + Math.round(value * 100) + '%'; },\n    });\n    const a = document.createElement('a'); a.href = URL.createObjectURL(output); a.download = 'software-aac-check.mp4'; a.click();\n    state.textContent = 'Complete: ' + output.size + ' bytes';\n  } catch (error) { state.textContent = error.name + ': ' + error.message; }\n});\ndocument.getElementById('cancel').addEventListener('click', () => abort?.abort());\n","tests/player.test.js":"import { test, expect } from 'bun:test';\nimport { readFileSync } from 'node:fs';\nimport { createHash } from 'node:crypto';\nimport { buildAudioPlayerHtml, audioBufferToWav } from '../src/vendor/yue-player.js';\nimport upstream from '../src/vendor/upstream.json';\n\ntest('all vendored Yue functions retain pinned upstream source hashes', () => {\n  const source = readFileSync(new URL('../src/vendor/yue-player.js', import.meta.url), 'utf8');\n  for (const item of upstream.functions) {\n    const from = source.indexOf(`function ${item.name}(`);\n    const next = source.indexOf('\\nfunction ', from + 1), end = next === -1 ? source.indexOf('\\nexport ', from) : next;\n    const original = source.slice(from, end).trimEnd();\n    expect(createHash('sha256').update(original).digest('hex')).toBe(item.sha256);\n  }\n});\ntest('original player embeds local media and escapes lyric markup', () => {\n  const html = buildAudioPlayerHtml({ title: '\u003cTitle>', source: 'data:audio/wav;base64,AAAA', accent: '#90efb8', lyrics: ['[Verse]', '\u003c/script>\u003cimg src=x onerror=alert(1)>'], timestamps: [{ line: 1, start: 0 }] });\n  expect(html).toContain('data-section=\"1\"');\n  expect(html).toContain('&lt;/script&gt;&lt;img');\n  expect(html).toContain('SELF-CONTAINED PLAYER &middot; MM-TOOLS');\n  expect(html).toContain('src=\"data:audio/wav;base64,AAAA\"');\n  expect(html.match(/\u003cscript>/g)?.length).toBe(1);\n  expect(html.match(/\u003c\\/script>/g)?.length).toBe(1);\n});\ntest('original WAV encoder emits PCM with actual duration/channels', () => {\n  const data = audioBufferToWav({ numberOfChannels: 1, length: 480, sampleRate: 48000, getChannelData: () => new Float32Array(480) });\n  expect(new TextDecoder().decode(data.slice(0, 4))).toBe('RIFF');\n  expect(new DataView(data.buffer).getUint32(40, true)).toBe(960);\n  expect(data.byteLength).toBe(1004);\n});\n","package.json":"{\n  \"name\": \"studio\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"license\": \"AGPL-3.0-only\",\n  \"scripts\": {\n    \"build\": \"bun scripts/build.ts\",\n    \"start\": \"bun scripts/serve.ts\",\n    \"dev\": \"bun run build && bun run start\",\n    \"test\": \"bun test\"\n  },\n  \"dependencies\": {\n    \"mediabunny\": \"1.62.1\",\n    \"@mediabunny/aac-encoder\": \"1.62.1\"\n  }\n}\n","bun.lock":"{\n  \"lockfileVersion\": 2,\n  \"configVersion\": 1,\n  \"workspaces\": {\n    \"\": {\n      \"name\": \"studio\",\n      \"dependencies\": {\n        \"@mediabunny/aac-encoder\": \"1.62.1\",\n        \"mediabunny\": \"1.62.1\",\n      },\n    },\n  },\n  \"packages\": {\n    \"@mediabunny/aac-encoder\": [\"@mediabunny/aac-encoder@1.62.1\", \"\", { \"peerDependencies\": { \"mediabunny\": \"^1.0.0\" } }, \"sha512-3fiZYAX95d+TDp2vu0sXMYputLm2+W21fZQMUWTf9awKhsRC/wko9OXj4GLLmGKMRryvI9Ocv9HzhhHVRYWopQ==\"],\n\n    \"@types/dom-mediacapture-transform\": [\"@types/dom-mediacapture-transform@0.1.12\", \"\", { \"dependencies\": { \"@types/dom-webcodecs\": \"*\" } }, \"sha512-d7/QsLRwF864A5mgIM/YrfiglHoYn7zgCcAoJgW404r+2DwnNr7EBbLnCWpmOMgH8y0te73L1AV6H1bmauaWFw==\"],\n\n    \"@types/dom-webcodecs\": [\"@types/dom-webcodecs@0.1.13\", \"\", {}, \"sha512-O5hkiFIcjjszPIYyUSyvScyvrBoV3NOEEZx/pMlsu44TKzWNkLVBBxnxJz42in5n3QIolYOcBYFCPZZ0h8SkwQ==\"],\n\n    \"mediabunny\": [\"mediabunny@1.62.1\", \"\", { \"dependencies\": { \"@types/dom-mediacapture-transform\": \"^0.1.11\", \"@types/dom-webcodecs\": \"0.1.13\" } }, \"sha512-lYzeerDwo9QLhBCipqQDXOSV7InvaIFplllZQviPO5rPwH+IUr8M1uvumk1olIUgMRGkPiInRriv25WFErUgMw==\"],\n\n    \"@types/dom-mediacapture-transform/@types/dom-webcodecs\": [\"@types/dom-webcodecs@0.1.19\", \"\", {}, \"sha512-+yFUIDUaASFz0vQpWBErPxun/Lb+F0TdrlTsj50gm7K797YzEx2TmV6fEiwciHyFNghlZYPgQXH5qRcwMHcJFQ==\"],\n  }\n}\n",".gitign